'use strict';
(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["pl"]={"g-flurpruefung":["Co obejmuje oględziny wizualne i funkcjonalne przed rozpoczęciem pracy?","Przed pierwszą misją tego dnia.","Sprawdź tylko poziom paliwa i kolor pojazdu.","Sprawdź hamulce, układ kierowniczy, widły, opony i urządzenia zabezpieczające zgodnie z instrukcją obsługi.","Przeprowadzić jazdę próbną z podniesionym ładunkiem.","Codzienna kontrola obejmuje części i funkcje istotne dla bezpieczeństwa zgodnie z instrukcją obsługi."],"g-rueckhalt":["Jak sobie radzisz z istniejącym systemem zabezpieczeń kierowcy?","Wózek widłowy posiada obowiązkowy system zabezpieczający.","Używaj go prawidłowo podczas jazdy.","Stosować wyłącznie na nierównych podłogach.","Dezaktywuj tę funkcję w przypadku krótkich podróży.","Przewidziane systemy przytrzymujące muszą być używane zgodnie z instrukcjami producenta; zapewniają szczególną ochronę w przypadku przewrócenia się."],"g-mangelmelden":["Co dotyczy wózka widłowego z uszkodzonymi widłami?","Sprawdzając widać wyraźnie wygięty ząb.","Jeśli to możliwe, rozłóż obciążenie na drugi ząb.","Jeździj tylko lekkimi ładunkami aż do następnego przeglądu.","Nie używaj wózka widłowego i zgłoś usterkę osobie odpowiedzialnej.","Uszkodzony sprzęt do obsługi ładunków może ulec awarii; Usterki związane z bezpieczeństwem wymagają wyłączenia do czasu wyjaśnienia."],"g-einweisung":["Przełączasz się na wózek widłowy z różnymi elementami sterującymi. Co jest wymagane przed użyciem?","Działanie różni się od poprzedniego pojazdu.","Instrukcja obsługi urządzenia i przestrzeganie instrukcji obsługi.","Zawsze wystarczy krótkie wyjaśnienie od niezaangażowanego kolegi.","Brak dodatkowych informacji w przypadku posiadania uprawnień na wózki widłowe.","Kwalifikacja ogólna nie zastępuje niezbędnej instrukcji dotyczącej faktycznie używanego urządzenia."],"g-anbaugeraet":["Powinieneś użyć załącznika. Co sprawdzasz w pierwszej kolejności?","Nowe urządzenie zmienia sposób podnoszenia ładunku.","Czy osprzęt odpowiada homologacji pojazdu i dopuszczalnemu obciążeniu.","Tylko czy urządzenie da się wizualnie przymocować.","Czy osprzęt można zainstalować bez dokumentacji.","Osprzęt może zmienić pozostały udźwig i środek ciężkości obciążenia; Należy sprawdzić atesty i informacje o nośności."],"g-diagramm":["Dlaczego potrzebujesz wykresu nośności?","Obecny jest duży ładunek, którego środek ciężkości znajduje się daleko na zewnątrz.","Aby określić najkrótszą trasę.","Aby ocenić maksymalne dopuszczalne obciążenie w zależności od wysokości podnoszenia i środka ciężkości ładunku.","Aby określić pojemność zbiornika.","Dopuszczalne obciążenia zależą między innymi od odległości środka ciężkości ładunku i wysokości podnoszenia."],"g-lastschwerpunkt":["Co zwykle dzieje się, gdy środek ciężkości przesuwa się dalej do przodu?","Długi ładunek wystaje daleko przed widłami.","Dopuszczalna nośność może się zmniejszyć.","Nośność stale rośnie.","Odległość nie ma wpływu na moment wywracający.","Większa odległość od środka ładunku zwiększa moment wywracający i może zmniejszyć dopuszczalną nośność."],"g-gabelabstand":["W jaki sposób widły powinny podnieść odpowiednią paletę?","Chcesz odebrać równomiernie załadowaną paletę.","Z zębami jak najbliżej siebie i tylko w jednym rogu.","Przy tak dużej odległości, że paleta przewraca się na bok.","Z odpowiednim rozstawem zębów i wystarczającą powierzchnią podwozia i podparcia.","Ładunek musi być bezpiecznie i równomiernie podparty na widłach."],"g-schieflast":["Ładunek jest ułożony niestabilnie. Co jest słuszne?","Pudła kartonowe mogą spaść po podniesieniu.","Zacznij powoli; ładunek stabilizuje się.","Przed podniesieniem ładunku należy go odpowiednio zabezpieczyć lub zlecić jego ponowny montaż.","Podnieś ładunek powyżej wysokości głowy, tak aby nie przeszkadzał.","Luźny lub niestabilny ładunek może spaść i stanowić zagrożenie dla ludzi; najpierw zastosować środki bezpieczeństwa."],"g-personen":["Czy można podnosić człowieka na zwykłych widłach?","Kolega chce dotrzeć do światła.","Tak, jeśli kolega nosi kask.","Nie, ludzie mogą korzystać wyłącznie z wyznaczonych i dozwolonych obiektów, zgodnie ze specjalnymi wymaganiami.","Tak, jeśli zbliży się tylko do niewielkiej wysokości.","Zwykłe widły nie są platformą do pracy osobistej; Transport i podnoszenie osób podlega specjalnym wymaganiom."],"g-transporthoehe":["Jak zazwyczaj transportujecie paletę?","Droga jest czysta i równa.","Z ładunkiem podniesionym tylko na tyle, na ile jest to konieczne i zgodnie z instrukcją obsługi.","Z ładunkiem podniesionym jak najwyżej, aby być lepiej widocznym.","Z masztem podnoszącym mocno pochylonym do przodu, niezależnie od ładunku.","Niska pozycja transportowa zmniejsza ryzyko przewrócenia się i kolizji; Decydujące znaczenie mają instrukcje dotyczące urządzenia."],"g-kurvenfahrt":["Dlaczego szybkie pokonywanie zakrętów wózkiem widłowym jest niebezpieczne?","Chcesz szybko zjechać z wąskiej ścieżki.","Bo to po prostu szybciej rozładowuje baterię.","Ponieważ wózek widłowy automatycznie lepiej steruje.","Ponieważ siły boczne wpływają na stabilność i mogą prowadzić do przewrócenia.","Podczas pokonywania zakrętów w grę wchodzą dodatkowe siły; prędkość należy dostosować do obciążenia i warunków."],"g-ladebruecke":["Co sprawdzasz przed wjazdem na most przeładunkowy?","Powinieneś jechać ciężarówką.","Tylko czy ścieżka wygląda na wystarczająco szeroką.","Ładowność, bezpieczne podparcie i zabezpieczenie przed przesunięciem oraz zabezpieczenie pojazdu.","Tylko czy oświetlenie jest włączone.","Mosty przeładunkowe i pojazdy muszą być zabezpieczone przed przemieszczaniem się i dostosowane do ładunku."],"g-fussgaenger":["Jak zachować się na skrzyżowaniu mylącym z pieszymi?","Połączenia wizualne są ograniczone.","Jedź z odpowiednią prędkością, w razie potrzeby zatrzymaj się i zadbaj o bezpieczną widoczność.","Zawsze zachowuj pierwszeństwo podczas przewożenia ładunku.","Po prostu zatrąb i jedź dalej.","Piesi mają szczególne potrzeby w zakresie ochrony; Prędkość, widoczność i komunikacja muszą być dostosowane do trasy ruchu."],"g-batterieladen":["Na co należy zwrócić szczególną uwagę podczas ładowania akumulatora napędu?","Wykorzystywana jest stacja ładowania akumulatorów.","Miejsce ładowania można wybrać niezależnie od instrukcji producenta.","Otwarty ogień jest dozwolony, gdy ciężarówka stoi nieruchomo.","Odpowiednia powierzchnia ładunkowa, wystarczająca wentylacja i wymagania producenta, a także ochrona przeciwpożarowa i przeciwwybuchowa.","Podczas ładowania mogą wystąpić zagrożenia związane z energią elektryczną, gazami i chemikaliami; należy przestrzegać przewidzianych środków ochronnych."],"h-beauftragt":["Na jakich warunkach wolno Ci samodzielnie obsługiwać platformę roboczą?","Powinieneś korzystać z platformy roboczej w firmie.","Jeśli posiadasz prawo jazdy na samochód.","Jeśli jesteś odpowiedni, poinstruowany lub wykwalifikowany i zatrudniony przez pracodawcę.","Jeśli kiedykolwiek widziałeś platformę roboczą.","Pracodawca musi zapewnić przydatność, kwalifikacje i zadania zgodnie z wymogami operacyjnymi."],"h-vorpruefung":["Co należy sprawdzić przed rozpoczęciem pracy na podnośniku koszowym?","Scena była na zewnątrz przez całą noc.","Test wizualny i funkcjonalny zgodnie z instrukcjami producenta, łącznie z urządzeniami zabezpieczającymi.","Tylko kolor i wiek sceny.","Czy materiał roboczy znajduje się już na platformie.","Przed użyciem należy sprawdzić maszynę, elementy sterujące, funkcje awaryjne i widoczne uszkodzenia zgodnie z instrukcją obsługi."],"h-tragfaehigkeit":["Jaka informacja określa dopuszczalne obciążenie kosza roboczego?","Dwie osoby chciałyby zabrać ze sobą dodatkowe narzędzia.","Ludzie mogą swobodnie oszacować dopuszczalną masę całkowitą.","Liczy się tylko waga najcięższej osoby.","Nie wolno przekraczać podanej nośności osób, narzędzi i materiałów.","Nominalne obciążenie odnosi się do całkowitego dopuszczalnego obciążenia, łącznie z przewożonym materiałem."],"h-untergrund":["O czym myślisz przed ustawieniem sceny z podporami?","Pracujesz w pobliżu wypełnionego obszaru.","Tylko w zasięgu boomu.","Sprawdź nośność i równość podłoża oraz odpowiednie podparcie zgodnie z instrukcją.","Na możliwie najmniejszej liczbie wysuniętych podpór.","Niewystarczające podłoże lub niewłaściwe podparcie może prowadzić do utraty stabilności."],"h-wind":["Zrywa się silny wiatr. Jak sobie z tym radzicie?","Znajdziesz się na scenie plenerowej.","Należy przestrzegać ograniczeń producenta i w przypadku ich przekroczenia przerwać pracę lub bezpiecznie opuścić kosz.","Rozsuń platformę tak daleko, jak to możliwe, aby była bardziej stabilna.","Reaguj tylko wtedy, gdy spadną luźne przedmioty.","Warunki wietrzne dopuszczone przez producenta stanowią ograniczenia w zastosowaniu; Wiatr może wytworzyć niebezpieczne dodatkowe siły."],"h-strom":["Musisz pracować w pobliżu napowietrznej linii energetycznej. Co jest kluczowe?","W obszarze roboczym znajduje się linia pod napięciem.","Kask zastępuje zachowanie bezpiecznej odległości.","Wystarczy odizolować kosz i pracować bez koordynacji.","Wyjaśnij obszar zagrożenia i zapewnij niezbędne odległości ochronne lub inne odpowiednie środki.","Przeskok elektryczny jest również możliwy bez bezpośredniego kontaktu; Przed rozpoczęciem operacji należy określić niezbędne środki ochronne."],"h-notablass":["Dlaczego należy znać procedurę awaryjnego opuszczania?","Możliwa jest awaria normalnego sterowania.","Aby w przypadku awarii możliwa była bezpieczna akcja ratunkowa w zależności od urządzenia.","Aby urządzenie działało szybciej podczas normalnej pracy.","Zastępuje regularne testowanie.","Przed użyciem należy zapoznać się ze sterowaniem awaryjnym, opuszczaniem awaryjnym i koncepcjami ratunkowymi."],"h-gelaender":["Jak uzyskać dodatkową wysokość w koszu roboczym?","Punkt montażowy jest tuż poza Twoim zasięgiem.","Wdrap się na płot koszowy.","Połóż deskę na poręczy.","Użyj odpowiedniej platformy o wystarczającej wysokości roboczej; nie wspinaj się po poręczach.","Wspinanie się po płotach lub prowizorycznych wzniesieniach zagraża zabezpieczeniu przed upadkiem."],"h-psaga":["Jakie wymagania mają zastosowanie do osobistego sprzętu chroniącego przed upadkiem z wysokości?","Korzystasz z platformy roboczej wyposażonej w system zabezpieczający.","Zawsze wystarczający jest dowolny punkt kotwiczenia poza koszem.","Należy przestrzegać oceny ryzyka, informacji producenta i odpowiednich punktów mocowania.","Nie należy stosować żadnych zabezpieczeń, jeśli kosz posiada poręcz.","To, czy i jakie środki ochrony indywidualnej są konieczne, określa ocena ryzyka, instrukcja budowy sceny i instrukcja obsługi."],"h-verfahren":["Czy scenę można przesuwać z podniesionym podestem?","Miejsce pracy jest kilka metrów dalej.","Tylko jeśli pozwala na to model i warunki pracy zgodnie z zaleceniami producenta.","Zawsze, o ile wszyscy się utrzymają.","Nie, nigdy, niezależnie od projektu i zgody producenta.","Ruch w pozycji podniesionej zależy od urządzenia i jest dozwolony wyłącznie w zatwierdzonych warunkach pracy."],"h-kollision":["O co należy zadbać podczas pracy w pobliżu dźwigów lub innych maszyn?","Ruchome części mogą dotrzeć do kosza roboczego.","Nic; kosz roboczy jest zawsze widoczny.","Zawsze przejeżdżaj koszem roboczym po innych maszynach.","Koordynuj obszary robocze, aby uniknąć kolizji lub punktów ucisku.","Jednoczesna praca maszyn wymaga skoordynowanych procesów pracy oraz zabezpieczenia przed kolizjami i zakleszczeniami."],"h-einstieg":["Jak wejść lub wyjść z koszyka pracy?","Do kosza dojdziesz na poziomie gruntu.","Przejdź przez zewnętrzną poręcz.","Poprzez zamierzony dostęp w bezpiecznym miejscu, zgodnie z instrukcją obsługi.","Poprzez umieszczoną obok drabinę z wysuniętym wysięgnikiem.","Należy przestrzegać zamierzonego dostępu i instrukcji producenta; Niekontrolowane wspinanie się na nie stwarza ryzyko upadku."],"h-defekt":["Funkcja zatrzymania awaryjnego nie działa. Co robisz?","Wadę odkryjesz podczas przeglądu.","Nie korzystaj z platformy i zgłoś usterkę.","Kontynuuj pracę, jeśli działają normalne elementy sterujące.","Przyklej przełącznik tak, aby nikt go nie obsługiwał.","Awaria urządzenia zabezpieczającego jest wadą mającą znaczenie dla bezpieczeństwa i uniemożliwia bezpieczną pracę."],"h-sicht":["Ruchu jezdnego nie można zobaczyć z powodu przeszkody. Jak sobie z tym radzisz?","Należy przenieść scenę mobilną.","Jedź powoli, bez widoczności.","Po prostu polegaj na wskaźniku odległości.","Zatrzymaj ruch i zapewnij widoczność lub poinstruuj zgodnie z instrukcją obsługi.","Przed zabiegiem należy dokonać bezpiecznego przeglądu ludzi, przeszkód i dróg komunikacyjnych."],"h-rettung":["Na czym polega planowanie rozmieszczenia w przypadku pracy na większych wysokościach?","Scena jest używana w odległym miejscu.","Tylko planowany czas pracy.","Odpowiednia koncepcja ratunkowa z dostępnymi, przeszkolonymi osobami i procedurami awaryjnego opuszczania.","Założenie, że straż pożarna natychmiast rozwiąże każdy problem.","Skuteczną akcję ratowniczą należy zorganizować z wyprzedzeniem, nawet jeśli zawiodą zwykłe kontrole."],"k-befaehigung":["Co jest potrzebne do samodzielnej obsługi dźwigu?","Pracę dźwigu ma przejąć nowy pracownik.","Przydatność i wymagane kwalifikacje, instruktaż i odpowiednie zadanie.","Wystarczy prawo jazdy na samochód.","Wystarczy raz obejrzeć.","Prace dźwigowe mogą być zlecane wyłącznie osobom wykwalifikowanym i upoważnionym; Częścią tego jest instrukcja obsługi sprzętu."],"k-funktionspruefung":["Co trzeba zrobić, aby sprawdzić dźwig przed rozpoczęciem zmiany?","Przejmujesz dźwig kryty.","Wystarczy przeczytać czas pracy na tabliczce znamionowej.","Sprawdź funkcje istotne dla bezpieczeństwa i widoczne usterki zgodnie z instrukcją obsługi.","Przetestuj żuraw przy maksymalnym obciążeniu bez sprawdzania.","Obowiązkowa kontrola eksploatacyjna ma na celu wczesną identyfikację niebezpiecznych usterek."],"k-traglast":["Jakie znaczenie ma dopuszczalna nośność?","Trzeba podnieść ładunek.","Jest to zalecenie niewiążące.","Ma to zastosowanie tylko wtedy, gdy hak jest całkowicie schowany.","Nie wolno przekraczać dopuszczalnego obciążenia dla danych warunków pracy.","Dopuszczalne obciążenia dla niektórych typów żurawi mogą zależeć od promienia, położenia wysięgnika i uzbrojenia."],"k-personen":["Co dotyczy osób znajdujących się pod zawieszonymi ładunkami?","Ładunek jest przesuwany po obszarze roboczym.","Strefa zagrożenia musi być wolna; nikt nie może wchodzić pod zawieszony ciężar.","Kask umożliwia przebywanie bezpośrednio pod nim.","Krótkie przejazdy są dozwolone, jeśli dźwig porusza się powoli.","Zawieszone ładunki stwarzają ryzyko upadku i zmiażdżenia; Należy trzymać ludzi z dala od strefy zagrożenia."],"k-signale":["Nie widzisz atakującego i otrzymujesz sprzeczne sygnały. Co robisz?","Komunikat jest niejasny.","Kontynuuj ostatnie polecenie jazdy.","Zatrzymaj ruch i wyraźnie wyjaśnij komunikację.","Odłóż ładunek szybciej, bez konsultacji.","Bezpieczne przemieszczanie ładunku wymaga jasnych sygnałów i jasnej komunikacji."],"k-sicht":["Kto zapewni wsparcie podczas transportu, jeśli operator dźwigu nie widzi w pełni ścieżki ładunku?","Kolumna w holu zasłania ścieżkę.","Osoba, która przechodzi obok bez wcześniejszej zgody.","Nikt; ważny jest tylko hak.","Odpowiednia, poinstruowana osoba z jasno uzgodnionym zrozumieniem.","Jeżeli droga obciążenia nie jest widoczna, wymagana jest odpowiednia instrukcja lub inne bezpieczne rozwiązanie."],"k-ruck":["Dlaczego należy unikać gwałtownych ruchów żurawia?","Ciężki ładunek zaczyna się kołysać.","Tworzą dodatkowe naprężenia dynamiczne i mogą destabilizować ładunek.","Zasadniczo redukują wszelkie ruchy wahadłowe.","Zawsze zwiększają nominalną nośność.","Siły przyspieszania i hamowania zwiększają obciążenie żurawia i zawiesi."],"k-sperrbereich":["Co należy sprawdzić przed przesunięciem ładunku w przestrzeni wspólnej?","W pobliżu pracują inni pracownicy.","Czy ładunek wizualnie pasuje do dźwigu.","Czy obszar zagrożenia jest zabezpieczony i czy ludzie nie są zagrożeni.","Czy ładunek można unieść jak najwyżej nad wszystkimi.","Na drogach obrotu i ładunku nie mogą znajdować się niechronione osoby."],"k-stuetzen":["Co jest istotne w przypadku żurawia samojezdnego z wysięgnikami?","Dźwig ustawia się na częściowo wypełnionym terenie.","Tylko szerokość drogi.","Kolor płyt nośnych.","Podstawa nośna oraz podparcie i rozkład obciążenia zgodnie z instrukcją montażu i producenta.","Instalacja ma istotny wpływ na stabilność, szczególnie w zmiennych warunkach gruntowych."],"k-wetter":["Podmuch wiatru powoduje znaczne kołysanie ładunku. Co jest słuszne?","Pracujesz na świeżym powietrzu.","Bezpiecznie zatrzymaj ruch i przestrzegaj dopuszczalnych warunków pracy.","Szybko przyspieszaj ruch.","Kontynuuj podnoszenie ładunku pomimo przekroczenia limitów producenta.","Wiatr i ruchy kołysające mogą zdestabilizować ładunek i dźwig; Należy przestrzegać ograniczeń stosowania."],"k-freileitung":["Co obowiązuje w przypadku używania dźwigów w pobliżu napowietrznych linii elektrycznych?","Wysięgnik lub ładunek mogą zbliżyć się do linii.","Przy obciążeniu nieprzewodzącym odstępy nie mają znaczenia.","Przed rozpoczęciem pracy wyjaśnij z osobami odpowiedzialnymi obszar zagrożenia i niezbędne środki ochronne.","Polegaj wyłącznie na własnej reakcji operatora dźwigu.","Występują niebezpieczeństwa związane z kontaktem i przeskokiem napięcia; wymagane są bezpieczne odległości ochronne lub inne środki."],"k-sichern":["Co robisz zanim opuścisz dźwig?","Praca zostaje przerwana.","Pozostawić ładunek zawieszony.","Pozostaw żuraw bez nadzoru z pracującym napędem.","Opuść bezpiecznie ładunek i zabezpiecz żuraw zgodnie z instrukcją obsługi.","Zawieszonych ładunków nie można pozostawiać bez kontroli; Żuraw i ładunek należy zaparkować w bezpieczny sposób."],"k-lastanschlag":["Skąd wiadomo, czy zastosowana chusta jest odpowiednia?","Ładunek należy podnosić za pomocą pasa do podnoszenia.","Pod względem oznakowania, nośności, stanu i przydatności do rodzaju mocowania.","Tylko po kolorze paska do podnoszenia.","Ponieważ był już używany wczoraj.","Nośność i stan muszą być wystarczające, biorąc pod uwagę warunki mocowania."],"k-stopp":["Na ścieżkę załadunku nieoczekiwanie wchodzi osoba. Co robisz?","Żuraw aktualnie przenosi ładunek.","Natychmiast zatrzymaj bezpiecznie ruch i oczyść obszar zagrożenia.","Wystarczy dać sygnał ostrzegawczy i jechać dalej.","Podnieś ładunek wyżej i przejedź po nim.","Należy chronić ludzi przed ruchami ładunku; Jeżeli istnieje bezpośrednie zagrożenie, należy przerwać ruch."],"k-neuerkran":["Otrzymasz dźwig z nieznanym sterowaniem. Co jest słuszne?","Sterowanie jest inne niż dotychczas.","Jeśli podejrzewasz, wypróbuj zwykłe klucze.","Pozwól komuś innemu bez przeszkolenia jechać z przodu.","Przed samodzielnym użyciem otrzymaj niezbędną instrukcję obsługi urządzenia.","Nawet doświadczeni operatorzy dźwigów potrzebują wiedzy na temat stosowanych specyficznych elementów sterujących, urządzeń ochronnych i ograniczeń."],"a-kennzeichnung":["Skąd wiesz, jakie jest dopuszczalne obciążenie zawiesia?","Chcesz wybrać chustę.","Zapach materiału.","Na odpowiednim, czytelnym oznaczeniu nośności i informacji producenta.","O długości czasu przechowywania.","Dopuszczalna nośność jest określona na podstawie oznakowania i warunków pracy."],"a-sichtpruefung":["Zauważasz wyraźne przecięcie paska do podnoszenia. Jak sobie z tym radzisz?","Opaska ma nieść ładunek.","Nie używaj taśmy i wyślij ją do sprawdzenia lub odrzucenia.","Zakryj rozcięcie taśmą.","Używaj go tylko do szczególnie lekkich ładunków.","Uszkodzone zawiesia tekstylne mogą zawieść i należy je ocenić zgodnie z kryteriami utylizacji."],"a-neigungswinkel":["Co się stanie, jeżeli kąt nachylenia cięgien zawiesia będzie większy od pionu?","Wieszak dwużyłowy rozkłada się bardziej.","Siły splotu zawsze maleją.","Siły splotu pozostają takie same.","Siły w pasmach rosną; Należy przestrzegać dopuszczalnych kątów i nośności.","Wraz ze wzrostem rozpiętości wzrasta siła rozciągająca na pasmo nośne."],"a-schwerpunkt":["Dlaczego musisz znać środek ciężkości ładunku?","Obciążenie rozkłada się nierównomiernie.","Aby ładunek podczas podnoszenia był stabilny i nie przewracał się w niekontrolowany sposób.","Aby wybrać kolor chust.","Aby ładunek można było szybciej obracać.","Niekorzystne punkty mocowania lub położenie środka ciężkości mogą prowadzić do przewrócenia się, poślizgu lub pochyłości."],"a-kantenschutz":["Pasek do podnoszenia opiera się o ostrą krawędź elementu. Co należy zrobić?","Element należy podnieść.","Szybko podnieś ładunek, zanim pas ulegnie uszkodzeniu.","Użyj odpowiedniego zabezpieczenia krawędzi i sprawdź rodzaj mocowania.","Powierzchnię ładunkową czyścić wyłącznie szmatką.","Ostre krawędzie mogą uszkodzić włókna nośne; sprzęt do zawieszania należy odpowiednio zabezpieczyć."],"a-haken":["Na co zwracasz uwagę przy zakładaniu chusty?","Używasz haka cargo.","Umieść chustę z boku końcówki haka.","Trzymaj klapę bezpieczeństwa otwartą na stałe.","Załaduj hak zgodnie z przeznaczeniem do podstawy haka i przestrzegaj urządzeń zabezpieczających.","Niedopuszczalne obciążenie końcówki haka i brak zabezpieczenia może spowodować jego wypięcie."],"a-knoten":["Czy można skrócić zbyt długi pas do podnoszenia za pomocą węzła?","Długość przystanku nie pasuje.","NIE; Należy używać wyłącznie odpowiedniego, zatwierdzonego typu zawiesia lub odpowiedniego sprzętu do zawieszania.","Tak, jeśli węzeł zostanie zaciągnięty bardzo mocno.","Tak, o ile ładunek jest aktualnie nieruchomy.","Węzły mogą znacznie osłabić zawiesia tekstylne i nie można improwizować przy regulacji długości."],"a-probehub":["Dlaczego ładunek jest początkowo podnoszony ostrożnie?","Chcesz bezpiecznie transportować.","Aby mogła jak najszybciej dojechać do pracy.","Aby sprawdzić położenie zawiesi, stabilność i środek ciężkości.","Ponieważ ładowność zwiększa się automatycznie.","Kontrolowany pierwszy skok pomaga wykryć nieprawidłowe zatrzymania i niestabilne położenie ładunku."],"a-lastweg":["Gdzie mogą przebywać ludzie podczas transportu ładunku?","Ładunek przemieszczany jest za pomocą dźwigu.","Bezpośrednio pod ładunkiem w kasku ochronnym.","Na ciężarze, jeśli uda im się utrzymać.","Poza obszarem zagrożenia i nie pod zawieszonymi ładunkami.","Nawet przy ostrożnym zamocowaniu nadal istnieje ryzyko upadku lub kołysania się ładunku."],"a-haende":["Jak uniknąć obrażeń spowodowanych zgnieceniem podczas odsadzania?","Ładunek zbliża się do powierzchni podparcia.","Trzymaj ręce i stopy z dala od obszaru zmiażdżenia i używaj odpowiednich pomocy.","Trzymaj ładunek gołą ręką.","Stań pomiędzy ładunkiem a ścianą, aby skorygować pozycję.","Pomiędzy ładunkiem a podporą powstają niebezpieczne punkty ściskające."],"a-vierstraenge":["Co dotyczy rozkładu obciążenia w zawieszeniu czterokołowym bez kompensacji obciążenia?","Dołączone jest sztywne obciążenie.","Wszystkie cztery pasma nieuchronnie niosą tę samą ilość.","Bez dowodu równomiernego rozkładu nośność nie może być wykorzystana jako ogólne oszacowanie dla czterech równomiernie obciążonych splotów.","Kąt nachylenia nie ma wtedy znaczenia.","W przypadku obciążeń sztywnych możliwe jest nierówne obciążenie splotu; Należy to uwzględnić przy projektowaniu i dopuszczalnej nośności."],"a-chemikalien":["Co obowiązuje w przypadku stosowania zawiesi tekstylnych mających kontakt z chemikaliami?","Pracujesz z nieznaną cieczą.","Kolor opaski niezawodnie świadczy o jej trwałości.","Każda opaska tekstylna jest odporna na działanie wszelkich substancji chemicznych.","Sprawdź trwałość i informacje o producencie; Nie używaj nieodpowiednich środków.","Substancje chemiczne mogą uszkodzić zawiesia i niezauważenie zmniejszyć ich nośność."],"a-aufbewahrung":["Jak przechowuje się chusty po użyciu?","Misja dobiegła końca.","Czyste, suche i zabezpieczone przed uszkodzeniami zgodnie ze specyfikacjami producenta.","Utknął na ziemi pod niezabezpieczonym ładunkiem.","Na dowolnym ostrym haku zewnętrznym.","Właściwe przechowywanie zapobiega przedwczesnemu zużyciu i ułatwia kontrolę wzrokową."],"a-auswahl":["Na co należy zwrócić szczególną uwagę w przypadku ładunków wrażliwych lub o ostrych krawędziach?","Pomalowany element maszyny ma zostać przeniesiony.","Tylko prędkość transportu.","Odpowiednie zawiesia i środki zabezpieczające powierzchnię ładunkową i krawędzie.","Niezależnie od obciążenia, zawsze ta sama linka stalowa.","Rodzaj mocowania i materiał muszą odpowiadać geometrii, powierzchni i zagrożeniu."],"a-abstimmung":["Operator dźwigu nie ma na ciebie widoku. Jak dajesz instrukcje?","Zostałeś przydzielony jako atakujący.","Machasz do woli, aż zacznie się ruch.","Wystarczy jeden telefon i odchodzisz.","Za pomocą wyraźnie uzgodnionych znaków lub innej niezawodnej komunikacji.","Atakujący i operatorzy dźwigów muszą się wyraźnie porozumiewać; Jeśli nie jest jasne, ruch należy zatrzymać."],"b-qualifikation":["Czego potrzebuje osoba, aby bezpiecznie obsługiwać koparkę hydrauliczną podczas pracy?","Prace na budowie powinna przejąć nowa osoba.","Odpowiednie kwalifikacje, instruktaż obsługi urządzenia i wymagane przydział.","Tylko prawo jazdy na samochód.","Wystarczy krótka obserwacja operacji.","Pracodawca musi zapewnić niezbędne kwalifikacje i poinstruować operatora odpowiednio do wykonywanego zadania."],"b-pruefung":["Co obejmuje codzienny przegląd maszyny?","Przejmujesz koparkę.","Sprawdź kolor lakieru i tapicerkę siedzeń.","Kontrola wzrokowa i testy funkcjonalne zgodnie z instrukcją obsługi, np. pod kątem nieszczelności i uszkodzeń.","Poruszaj wysięgnikiem z pełną prędkością, aż się zatrzyma.","Uszkodzenia układu hydraulicznego, podwozia i urządzeń zabezpieczających mogą prowadzić do poważnych wypadków."],"b-leitungen":["Co należy wiedzieć o rurach podziemnych przed rozpoczęciem kopania?","Powinieneś wykopać rów.","Tylko przybliżona głębokość planowanego wykopu.","Kolor oznaczeń naziemnych jest wystarczający.","Wyjaśnij lokalizację możliwych linii i określ odpowiednie środki bezpieczeństwa i eksploracji.","Uszkodzenie rur elektrycznych, gazowych lub wodociągowych może zagrażać życiu."],"b-schwenkbereich":["Jak zabezpieczyć osoby znajdujące się w obszarze obrotu koparki?","Zbierasz materiał za pomocą wysięgnika.","Odgradzaj lub zabezpiecz obszar zagrożenia i trzymaj ludzi z daleka.","Przed obróceniem należy powoli przesuwać łopatę.","Przejedź obszar nad głowami.","Obrotowa konstrukcja i sprzęt roboczy stwarzają ryzyko zmiażdżenia i uderzenia."],"b-boeschung":["Co jest ważne podczas pracy przy krawędzi wykopu?","Koparka stoi na ugruntowanym lub wypełnionym podłożu.","Tylko głębokość kopania określa dopuszczalne umiejscowienie.","Należy zwrócić uwagę na nośność i zabezpieczenie krawędzi oraz wymagane odległości zgodnie z oceną ryzyka.","Jedź jak najbliżej krawędzi, aby zaoszczędzić zasięg.","Jeśli nie ma wystarczającego prześwitu lub stabilnego podłoża, nasyp może się zawalić, a maszyna może spaść."],"b-standsicherheit":["Dlaczego nachylenie i podłoże są kluczowe podczas użytkowania?","Plac budowy znajduje się na zboczu.","Maszyna jest równie stabilna na każdej powierzchni.","Podwozia gąsienicowe eliminują ryzyko przewrócenia się.","Nierówności i nachylenia mogą wpływać na stabilność; Przestrzegać ograniczeń stosowania.","Stabilność i bezpieczeństwo przewrócenia zależą od podłoża, wyposażenia, ładunku i położenia maszyny."],"b-wechselgeraet":["Co należy sprawdzić po wymianie łyżki koparki za pomocą szybkozłącza?","Zainstalowano nowy załącznik.","Czy jest prawidłowo zamknięty i zabezpieczony zgodnie z instrukcją obsługi.","Tylko czy kolor łopaty pasuje.","Czy hydraulika pracuje tak cicho, jak to możliwe.","Wadliwe zamki mogą spowodować upadek osprzętu."],"b-heben":["Na co należy zwrócić uwagę podczas podnoszenia swobodnie wiszącego ładunku koparką?","Koparka służy do podnoszenia.","Decydująca jest tylko zwykła siła kopania.","Należy przestrzegać dopuszczalnego obciążenia podnoszenia, odpowiednich punktów mocowania i zalecanych urządzeń ochronnych.","Ładunek można zaczepić na zębach łyżki.","Podnoszenie jest dozwolone wyłącznie w przewidzianych warunkach pracy przy użyciu odpowiedniego sprzętu."],"b-rueckwaerts":["Musisz zawrócić, ale nie widzisz ścieżki. Co jest słuszne?","W pobliżu są inni pracownicy.","Jedź ostrożnie, tak aby nie było widoczności.","Po prostu zatrąb i jedź dalej.","Zatrzymaj się, zapewnij widoczność i obszar zagrożenia lub zorganizuj odpowiednie instrukcje.","Cofanie nie może stwarzać zagrożenia dla ludzi; ograniczona widoczność wymaga dodatkowych środków."],"b-kabel":["Wysięgnik mógł zbliżyć się do napowietrznej linii energetycznej. Co robisz?","Pracujesz na ciasnym placu budowy.","Wyjaśnij wcześniej z osobami odpowiedzialnymi obszar zagrożenia i odpowiednie środki ochronne.","Zignoruj ​​linię, jeśli wysięgnik jest pomalowany.","Poruszaj wysięgnikiem tylko szczególnie szybko.","Zagrożenia elektryczne powstają w wyniku kontaktu i przeskoku; konieczne są bezpieczne odległości i środki ochronne."],"b-verlassen":["Jak zaparkować koparkę przed wyjazdem?","Robisz sobie przerwę.","Pozostaw wysięgnik swobodnie pływający.","Bezpiecznie odstaw sprzęt roboczy i zabezpiecz maszynę przed przemieszczaniem się i nieuprawnionym użyciem.","Pozostaw uruchomiony silnik i otwartą kabinę.","Opuszczony sprzęt roboczy i zabezpieczenie przed niezamierzonym ruchem zmniejszają ryzyko wypadków."],"b-hydraulik":["Zauważasz olej hydrauliczny pod wysokim ciśnieniem na uszkodzonym przewodzie. Co jest słuszne?","Linia przecieka.","Poczuj wyciek ręką.","Zamocuj nowy zacisk pod ciśnieniem.","Wyłączyć maszynę w bezpieczny sposób, pozwolić na obniżenie ciśnienia i zlecić naprawy autoryzowanemu personelowi specjalistycznemu.","Płyn hydrauliczny pod wysokim ciśnieniem może spowodować poważne obrażenia; nigdy nie sprawdzaj wycieków ręcznie."],"b-unterbau":["Jakie jest niebezpieczeństwo jazdy po niestabilnej nawierzchni?","Ziemia po deszczu jest miękka.","Maszyna może opaść, zsunąć się lub przewrócić.","Napęd automatycznie staje się szerszy.","Dzięki temu zakres obrotu jest bezpieczniejszy.","Niewystarczająca nośność może znacząco pogorszyć stabilność i bezpieczeństwo jazdy."],"b-arbeitsgeraet":["Czy ktoś może pracować pod podniesionym narzędziem?","Człowiek chce coś zapanować pod łopatą.","Tak, gdy silnik pracuje na biegu jałowym.","Nie, nie bez wymaganego bezpiecznego podparcia i zabezpieczenia sprzętu roboczego.","Tak, jeśli dana osoba nosi kask ochronny.","Sprzęt hydrauliczny może zatonąć; Prace konserwacyjne wymagają bezpiecznego sprzętu roboczego."],"b-geraeteart":["Przesiadasz się z koparki hydraulicznej na ładowarkę kołową. Co jest wymagane?","Działanie i zachowanie podczas ruchu są różne.","To samo obuwie.","Jazda próbna bez instrukcji.","Kwalifikacje lub szkolenie wymagane dla nowego typu maszyny.","Kwalifikacja musi odpowiadać rodzajowi używanej maszyny i konkretnym wymaganiom operacyjnym."],"g-neigung":["Jeździsz załadowanym wózkiem widłowym po pochyłości. Co jest ważne?","Trasa ma wyraźne nachylenie.","Zawsze prowadź ładunek w dół pochyłości, nawet jeśli jest ciężki.","Prowadź ładunek pod górę i przestrzegaj wskazówek eksploatacyjnych dotyczących jazdy po pochyłościach.","Niezależnie od kierunku jazdy widły należy podnieść maksymalnie.","Na wzniesieniach i zjazdach ładunek należy zawsze przenosić pod górę; Należy przestrzegać instrukcji pojazdu i obsługi."],"g-gabelabsenken":["Dlaczego podczas parkowania widelec musi być opuszczony?","Wózek widłowy jest zaparkowany na przerwę.","Aby inni mogli skorzystać z widelców i wspiąć się na górę.","Aby widelec był lepiej widoczny z daleka.","Aby podnoszenie ładunku nie powodowało niepotrzebnego ryzyka potknięcia się lub obrażeń.","Opuszczone urządzenia do obsługi ładunku zmniejszają ryzyko wypadków na skutek wystających lub niezabezpieczonych wideł."],"g-fahrerwechsel":["Kolega chciałby pożyczyć wózek widłowy. Co musi być obecne?","Kolega ma od Ciebie jedynie ustną zgodę.","Musi posiadać niezbędne kwalifikacje i mandat operacyjny.","Twoje własne zadanie automatycznie dotyczy także jego.","W przypadku każdej firmy wystarczające jest prawo jazdy na samochód prywatny.","Niezależne przywództwo jest powiązane z przydatnością osobistą, szkoleniem, kwalifikacjami i przydziałem operacyjnym."],"g-ladungssicherung":["Paleta zawiera luźne, ułożone w stos pudełka. Co jest słuszne?","Pudełko kartonowe może spaść podczas jazdy.","Przed transportem należy zabezpieczyć ładunek przed poślizgiem i upadkiem.","Po szczególnie nierównym terenie należy jechać powoli.","Luźne pudełka zrekompensuj wyższą pozycją wideł.","Ładunek musi być stabilny i zabezpieczony przed upadkiem przed transportem wózkiem widłowym."],"g-bodenbelastung":["Przed tobą leży koc o ograniczonej nośności. Jak decydujesz?","Trasa prowadzi po poziomie średniozaawansowanym.","Zwróć tylko uwagę na masę ciężarówki bez ładunku.","Wyjaśnij dopuszczalne obciążenie podłogi dla wózków widłowych i ładunków.","Jedź z rozpędem, aby sufit był obciążony przez krótszy czas.","Istotny jest całkowity rzeczywisty nacisk na powierzchnię, włączając pojazd, obciążenie i wpływy dynamiczne."],"g-verkehrswege":["Oznaczona ścieżka dla pieszych przecina twoją ścieżkę. Co jest słuszne?","Piesi mogą w każdej chwili wejść na przejście.","Zawsze możesz uzyskać pierwszeństwo za pomocą klaksonu.","Możesz przejechać przez oznaczenie bez bycia obserwowanym.","Dostosuj prędkość, zwracaj uwagę na pieszych i kontynuuj jazdę tylko wtedy, gdy droga jest wolna.","Trasy komunikacyjne należy prowadzić z uwzględnieniem ludzi; Znaki ostrzegawcze nie zastępują bezpiecznej widoczności i jasnej trasy."],"g-parkbremse":["Parkujesz wózek widłowy na równym podłożu. Co to obejmuje?","Chcesz na kilka minut opuścić fotel kierowcy.","Zaparkuj, zaciągnij hamulec postojowy i zabezpiecz przed nieupoważnionym użyciem.","Pozostawiaj pojazd wyłącznie w pozycji neutralnej.","Widelec należy pozostawić na wysokości głowy, tak aby nikt go nie dotykał.","Przed wyjazdem należy bezpiecznie zatrzymać wózek i zabezpieczyć przed niezamierzonym przemieszczeniem."],"g-typenschild":["Które informacje są wiążące w przypadku ładunku na wózku widłowym?","Chcesz podnieść ciężką maszynę.","Szacunkowa ładowność na podstawie wielkości pojazdu.","Dane producenta na wykresie udźwigu lub nośności.","Waga ostatniej przewożonej palety.","Dopuszczalne obciążenie jest określone na podstawie informacji producenta i zależy między innymi od środka ciężkości obciążenia i wysokości podnoszenia."],"g-tore":["Podchodzisz do niskiego przejścia z wózkiem widłowym. Co sprawdzasz?","Na pojeździe znajduje się ogromny ładunek.","Czy możliwy jest bezpieczny przejazd wraz z ładunkiem i mocowaniem.","Tylko wysokość karetki wideł bez ładunku.","Czy uda Ci się przejechać szybciej, zanim brama się zamknie.","Przed przejazdami należy uwzględnić wysokość i szerokość w świetle oraz wymiary ładunku i pojazdu."],"g-reifen":["Podczas codziennej kontroli zauważasz mocno uszkodzoną oponę. Co robisz?","Na oponie widoczne są uszkodzenia istotne dla bezpieczeństwa.","Jeździsz powoli aż do regularnej wizyty konserwacyjnej.","Zwiększasz ciśnienie w oponach i jedziesz dalej.","Nie dopuszczasz pojazdu do eksploatacji i nie zgłaszasz szkody.","Uszkodzone opony mogą pogarszać stabilność i prowadzenie; wadę należy usunąć przed użyciem."],"h-absperren":["Pracownicy przechodzą pod platformą roboczą. Co jest konieczne?","Istnieje niebezpieczeństwo spowodowane spadającymi narzędziami.","Odpowiedni obszar ochronny lub ograniczony pod miejscem pracy.","Tylko uwaga przy pierwszym przejściu.","Narzędzia przechowuj jak najdalej od krawędzi kosza.","Miejsce pracy pod podniesionymi stanowiskami pracy należy zabezpieczyć przed niebezpieczeństwem ze strony spadających części."],"h-werkzeuge":["Jak transportować narzędzia w koszu roboczym?","Na wysokości potrzebnych jest kilka małych narzędzi.","Umieść je luźno na poręczy, tak aby były w zasięgu ręki.","Przechowywać i zabezpieczać w taki sposób, aby nie spadły i nie utrudniały obsługi.","Przymocuj do zewnętrznej części poręczy w kieszeni.","Luźne przedmioty mogą spaść i stanowić zagrożenie dla ludzi; wymagane jest bezpieczne przechowywanie."],"h-abstuetzung":["Podpora stoi na pokrywie studzienki. Co należy sprawdzić?","Chcesz podnieść platformę.","Upewnij się tylko, że pokrywa jest sucha.","Czy obciążenie może zostać bezpiecznie przejęte w tym momencie.","Czy inne podpory nie muszą być używane.","Podłoże i obszary styku muszą być w stanie bezpiecznie przyjąć siły nośne; Okładki należy oceniać osobno."],"h-notaus":["Kiedy należy zastosować urządzenie zatrzymujące awaryjnie?","Natychmiast następuje niebezpieczny ruch.","Tylko pod koniec zwykłej zmiany.","Do zatrzymywania w przypadku ostrego zagrożenia zgodnie z instrukcją obsługi.","Jako zamiennik planowanego obniżenia.","Wyłącznik awaryjny służy do zapobiegania niebezpieczeństwu, a nie do zwykłego sterowania lub normalnego wyłączania."],"h-schraegstellung":["Zareaguje ostrzeżenie o przechyleniu stolika. Jak reagujesz?","Maszyna stoi na pochyłej powierzchni.","Zignorujesz ostrzeżenie przy małych wysokościach roboczych.","Pomimo ostrzeżenia, podjeżdżasz do najwyższej pozycji podnoszenia.","Zatrzymujesz się i doprowadzasz scenę do stanu bezpiecznego zgodnie z instrukcją producenta.","Ostrzeżenia o przechyleniu mogą wskazywać na niewystarczającą stabilność; dalsze ruchy nie mogą zwiększać zagrożenia."],"h-umgebung":["Co należy zorganizować podczas ustawiania w pobliżu obszaru ruchu?","Pojazdy mogą dotykać sceny.","Ochrona przed kolizjami i odpowiednie prowadzenie ruchu drogowego.","Przesuń kosz roboczy jak najdalej nad jezdnię.","Tylko ostrzeżenie przed uruchomieniem.","Podesty ruchome muszą być zabezpieczone przed kolizjami z użytkownikami dróg; instalację należy odpowiednio zabezpieczyć."],"h-ueberlast":["Włącza się ostrzeżenie o przeciążeniu w koszu. Co robisz?","Zaproszono dodatkowe narzędzia.","Zakończ pracę z większą prędkością.","Ustal dopuszczalne obciążenie kosza i postępuj zgodnie z instrukcją producenta.","Wyłączyć na stałe sygnał ostrzegawczy.","Nie wolno przekraczać maksymalnego dopuszczalnego obciążenia kosza, łącznie z ludźmi i materiałem."],"h-quetschen":["Wjeżdżasz z koszem pod dach. Które niebezpieczeństwo jest szczególnie istotne?","Nad koszem pozostało niewiele miejsca.","Zaciśnięcie lub zgniecenie pomiędzy koszem a konstrukcją.","Że silnik zużywa więcej paliwa.","Aby kierunek jazdy zawsze zmieniał się automatycznie.","Wąska przestrzeń nad lub obok kosza roboczego może spowodować poważne obrażenia z powodu zmiażdżenia."],"h-stromausfall":["Scena pozostaje na dużej wysokości bez głównego napędu. Co jest słuszne?","Normalne sterowanie koszem już nie odpowiada.","Schodzisz po wysięgniku bez bezpieczeństwa.","Czekasz do końca swojej zmiany bez powiadomienia.","Rozpocznij przygotowaną akcję ratowniczą z udziałem przeszkolonych osób i awaryjne opuszczanie.","W przypadku zakłóceń należy zaplanować bezpieczną akcję ratowniczą; Przeszkoleni ludzie muszą znać funkcje awaryjne."],"h-transportstellung":["Jak przygotować grunt pod transport?","Podest ruchomy ładuje się na odpowiedni pojazd.","Ustaw wysięgnik i platformę w pozycji transportowej zgodnie z instrukcją obsługi.","Przywiąż platformę tak daleko, jak to możliwe.","Pozostaw podpory wysunięte, aby zajmowały więcej miejsca.","Zalecana pozycja transportowa i zabezpieczenie ładunku opierają się na danych producenta i specyfikacjach transportowych."],"k-bremsprobe":["Co wykazuje próba działania hamulca dźwigu przed jego użyciem?","Chcesz móc bezpiecznie utrzymać ładunek.","Czy hamulec zatrzymuje się i utrzymuje ruch zgodnie z zamierzeniami.","Tylko czy oświetlenie kabiny działa.","Czy hak może automatycznie utrzymać ładunek.","Przed użyciem należy sprawdzić funkcje istotne dla bezpieczeństwa zgodnie ze specyfikacjami."],"k-schraegzug":["Czy za pomocą dźwigu można ciągnąć boczny ładunek pod kątem?","Hak nie znajduje się pionowo nad ładunkiem.","Tak, jeśli dźwig nadal ma rezerwę udźwigu.","Nie, ładunków nie wolno ciągnąć za pomocą niedopuszczalnych pociągnięć ukośnych.","Tak, jeśli chusty są szczególnie krótkie.","Ciągnięcie po przekątnej może powodować niekontrolowane ruchy i dodatkowe obciążenie dźwigu i zawiesi."],"k-verhakt":["Na podkonstrukcji wisi ładunek. Co jest słuszne?","Podczas podnoszenia odczuwalny jest opór.","Podnoś tak długo, aż samo przejdzie.","Gwałtownie przesuwasz ładunek na boki.","Zatrzymujesz się i bezpiecznie usuwasz zapięcie lub blokadę.","Zablokowanego ładunku nie wolno rozrywać na siłę, ponieważ mogą wystąpić niedopuszczalne siły."],"k-anzuheben":["Co sprawdzasz, gdy po raz pierwszy na krótko podnosisz zawieszony ładunek?","Ładunek unosi się kilka centymetrów nad ziemię.","Czy wisi w równowadze, a przystanek jest bezpieczny.","Czy dana osoba może postawić się bezpośrednio pod ładunkiem.","Czy żuraw stanie się bardziej stabilny dzięki szybkiemu skręceniu.","Krótkie kontrolowane podnoszenie służy do sprawdzenia osprzętu, wyważenia i bezpiecznego zachowania ładunku."],"k-lastweg":["Gdzie powinna przebiegać trasa transportu ładunku dźwigiem?","Pod możliwą ścieżką obciążenia znajduje się kilka stanowisk pracy.","Jeśli to możliwe, nad zajmowanymi stanowiskami pracy.","Na zaplanowanej, czystej ścieżce, bez zagrożeń dla ludzi.","Zawsze po przekątnej przez najbardziej ruchliwy obszar.","Trasy ładunku muszą być zorganizowane w taki sposób, aby nie zagrażać ludziom zawieszonym ładunkiem."],"k-signalverlust":["Łączność radiowa z marszałkiem zostaje zerwana. Co robisz?","Nie możesz zobaczyć samej ścieżki ładowania.","Kontynuujesz ruch powoli.","Eksperymentalnie odchylasz się w poprzednim kierunku.","Zatrzymujesz ruch, dopóki nie nastąpi jasne i bezpieczne zrozumienie.","W przypadku braku komunikacji mylący ruch ładunku może nie być kontynuowany."],"k-haken":["Hak zabezpieczający nie zamyka się niezawodnie. Co jest słuszne?","Podczas kontroli stwierdza się wadliwe zamknięcie.","Przed dalszym użyciem należy fachowo naprawić błąd.","Mocno zawiązujesz zapięcie za pomocą opaski kablowej.","Haczyka używasz tylko do lekkich ładunków.","Wadliwe urządzenia zabezpieczające na hakach ładunkowych mogą prowadzić do odczepienia się zawiesi i należy je naprawić."],"k-zugrichtung":["Co jest ważne dla pionowego podparcia ładunku?","Ładunek należy podnieść z maszyny.","Hak dźwigu powinien znajdować się powyżej środka ciężkości ładunku.","Hak powinien być ustawiony możliwie na bok.","Przed podniesieniem ładunek należy popchnąć.","Działanie siły możliwie najbardziej pionowe nad środkiem obciążenia pozwala uniknąć niedopuszczalnych sił poprzecznych i niekontrolowanego wychylenia."],"k-wartung":["Na dźwigu słychać nietypowy dźwięk zgrzytania. Jak sobie z tym radzisz?","Hałas pojawia się podczas podnoszenia.","Zakryj hałas, zwiększając prędkość.","Zatrzymaj bezpiecznie działalność, zgłoś usterki i poproś o ich wyjaśnienie.","Kontynuuj pracę bez uprzedzenia aż do przerwy.","Zauważalne zmiany mogą wskazywać na uszkodzenia istotne dla bezpieczeństwa i wymagają kontroli."],"k-absetzen":["Co należy zagwarantować podczas opuszczania ładunku dźwigiem?","Ciężki ładunek jest umieszczony na powierzchni.","Ładunek może leżeć niezabezpieczony na pochyłej powierzchni.","Zawiesia są usuwane, gdy zwierzę wciąż pływa.","Ładunek jest stabilny i zabezpieczony przed przewróceniem się lub przetoczeniem.","Ładunek można zdjąć z zawiesia dopiero po jego bezpiecznym odłożeniu i stwierdzeniu stabilności."],"l-schwerpunkt":["Dlaczego przed uderzeniem trzeba znać środek ciężkości?","Do transportu przeznaczona jest maszyna o kształcie asymetrycznym.","Aby ładunek podczas podnoszenia był jak najbardziej zrównoważony.","Aby chusty można było wybrać tak długo, jak to konieczne.","Aby dopuszczalna nośność nie odgrywała roli.","Położenie środka ciężkości wpływa na rozkład obciążenia i bezpieczną równowagę podczas podnoszenia."],"l-etikett":["Pas do podnoszenia nie posiada czytelnej etykiety udźwigu. Co jest słuszne?","Oznaczenie stało się nie do poznania.","Oszacuj nośność na podstawie koloru.","Nie używaj pasa do podnoszenia, dopóki nie zostanie wyraźnie wykazane, że jest on odpowiedni.","Pasa należy używać tylko raz, w przypadku małych ładunków.","W przypadku zawiesi wymagane jest odpowiednie oznaczenie; Niewyjaśniona nośność uniemożliwia bezpieczny wybór."],"l-kantenschutz":["Tekstylna opaska leży na ostrej stalowej krawędzi. Co jest konieczne?","Ładunek ma ostre krawędzie.","Pociągnij opaskę tak mocno, jak to możliwe, bez zabezpieczenia.","Wykonaj ruch szybciej.","Stosować odpowiednie zabezpieczenie krawędzi lub inny odpowiedni sprzęt do zawieszania.","Ostre krawędzie mogą uszkodzić lub przeciąć chusty tekstylne; wymagana jest odpowiednia ochrona."],"l-spreizwinkel":["Jak większy kąt nachylenia wpływa na obciążenie zawiesi?","Ładunek podnosi się za pomocą dwóch ukośnych lin.","Przy mniej korzystnych kątach siły w pasmach mogą wzrosnąć.","Siły pasma zanikają.","Kąt nie ma wpływu na naprężenie.","Przy mniej korzystnym kącie zatrzymania siły na pasmo mogą wzrosnąć; Należy przestrzegać tabel nośności."],"l-knoten":["Czy linę chusty można dowolnie skrócić za pomocą węzła?","Lina jest za długa w stosunku do planowanego obciążenia.","Tak, ciasny węzeł poprawia nośność.","Nie, należy używać wyłącznie zatwierdzonych metod skracania i kotwienia.","Tak, jeśli węzeł jest zabezpieczony taśmą.","Niedopuszczalne węzły osłabiają zawiesia i zmieniają ich dopuszczalną nośność."],"l-zeichen":["Co dotyczy komunikacji z osobą obsługującą dźwig?","Ścieżka ładunku jest częściowo zasłonięta.","Kilka osób jednocześnie daje różne sygnały.","Stosowane są jasne, wcześniej uzgodnione sygnały.","W przypadku dźwigów radiowych komunikacja nigdy nie jest wymagana.","Jasne znaki i jasne obowiązki zapobiegają niebezpiecznym nieprawidłowym ruchom."],"l-sichtpruefung":["Kiedy należy sprawdzić chusty pod kątem widocznych wad?","Chcesz użyć łańcuszka do noszenia.","Przed użyciem należy zwrócić uwagę na widoczne na zewnątrz uszkodzenia.","Tylko jeśli wypadek już się wydarzył.","Tylko raz przy pierwszym zakupie.","Przed każdym użyciem należy ocenić warunki bezpiecznej pracy; Widoczne uszkodzenia uniemożliwiają bezpieczne użytkowanie."],"l-drehung":["Podniesiony ładunek zaczyna się niekontrolowanie obracać. Co robisz?","Ładunek porusza się po ścieżce obciążenia.","Wkładasz rękę między ładunek a ścianę.","Poddajesz się temu ciężarowi i trzymasz się go.","Zachowujesz dystans i pozwalasz, aby ruch zatrzymał się w kontrolowany sposób.","Niekontrolowane ruchy ładunku stwarzają ryzyko zmiażdżenia i uderzenia; Ludzie muszą opuścić strefę niebezpieczną."],"l-ablegen":["Kiedy można zdjąć zawiesia z ładunku?","Ładunek jest umieszczony na kozłach.","Jeżeli ładunek jest stabilny i zabezpieczony przed przewróceniem się lub stoczeniem.","Gdy tylko dotknie ziemi po raz pierwszy, niezależnie od jej położenia.","Wciąż unosząc się w powietrzu, aby zaoszczędzić czas.","Zawiesia można zdejmować dopiero po ich bezpiecznym i stabilnym odłożeniu."],"l-ketten":["Zawiesie łańcuchowe ma mocno wygięte ogniwo. Co robisz?","Uszkodzenia są widoczne jeszcze przed podniesieniem.","Owiń uszkodzony obszar drutem.","Wycofaj łańcuch z użytku i oddaj go do profesjonalnego sprawdzenia.","Podnoś ładunek tylko o połowę wyżej.","Zdeformowane ogniwa łańcucha to widoczne uszkodzenia, które mogą uniemożliwić bezpieczne użytkowanie."],"b-einweiser":["Co jest ważne, gdy widoczność z koparki jest ograniczona?","Część budynku zasłania obszar dojazdowy.","Odpowiednie środki wizualne lub instrukcje i jasna komunikacja.","Tylko uważaj na kaptur.","Przejedź przez obszar obrotu, będąc niewidocznym.","Jeżeli widoczność jest ograniczona, należy zapobiegać zagrożeniom za pomocą dodatkowych środków organizacyjnych i technicznych."],"b-aushub":["Gdzie można składować urobek w pobliżu wykopu budowlanego?","Krawędź wykopu nie może być narażana na dodatkowe ryzyko.","Układać bezpośrednio na krawędzi, tak aby podjazdy pozostały wolne.","Przechowywać w wystarczająco bezpiecznej odległości i zgodnie ze specyfikacjami placu budowy.","Umieścić na luźnym podparciu bez dalszych testów.","Wykopany materiał może zagrozić nasypom i podparciom z powodu dodatkowych obciążeń; Należy zachować bezpieczne odległości."],"b-personen":["Czy w obszarze obrotu koparki mogą przebywać osoby?","Osoba chce mierzyć podczas panoramowania.","Tak, pod warunkiem, że nosi kask ochronny.","Tak, jeśli koparka kołysze się powoli.","Nie, strefa niebezpieczna musi być wolna przed rozpoczęciem ruchu.","W obszarze obrotu istnieje ryzyko poważnych obrażeń z powodu zmiażdżenia i uderzenia; teren musi być czysty."],"b-ladung":["Jak bezpiecznie transportować materiał ładowarką kołową?","Napełnioną łopatę należy przejechać po podwórku.","Z odpowiednio niską pozycją transportową i wolną ścieżką.","Z podniesioną łopatą dla lepszej widoczności.","Z otwartymi drzwiami i dużym kątem skrętu.","Odpowiednia pozycja transportowa zmniejsza ryzyko wywrócenia się i poprawia stabilność jazdy."],"b-anbaupruefung":["Co sprawdzasz po podłączeniu osprzętu?","Dołączona została nowa łopata.","Tylko czystość lakieru.","Bezpieczne zamykanie i działanie zgodnie z instrukcją obsługi.","Tylko czy urządzenie z zewnątrz wygląda tak samo.","Nieprawidłowe zablokowanie szybkozłączy może prowadzić do niezamierzonego zwolnienia osprzętu."],"b-einstieg":["Jak bezpiecznie dostać się do kabiny koparki?","Schody są brudne po deszczu.","Wejdź na kabinę po wysięgniku.","Dostań się na gąsienice jednym skokiem.","Korzystaj z wyznaczonych stopni i uchwytów oraz czyść brudne stopnie.","Odpowiednie podjazdy i bezpieczne punkty mocowania zmniejszają ryzyko poślizgu i upadku."],"b-graben":["Ściana wykopu wykazuje pęknięcia i rozpada się. Co jest słuszne?","Pracujesz tuż przy rowie.","Przerwij pracę i poproś osoby odpowiedzialne o zabezpieczenie wykopu.","Wystarczy podjechać bliżej krawędzi, aby zamknąć rów.","Pogłębiaj rów dalej bez zabezpieczenia.","Pęknięcia i ruchy podłoża mogą wskazywać na niestabilność i wymagać dalszej oceny bezpieczeństwa."],"b-betanken":["Na co zwracasz uwagę podczas tankowania maszyny do robót ziemnych?","Zbiornik jest prawie pusty.","Zabezpiecz silnik i źródła zapłonu zgodnie z instrukcjami producenta i unikaj rozlania.","Zawsze uzupełniaj benzynę lub olej napędowy w kabinie.","Dym podczas tankowania, gdy nie ma wiatru.","Zagrożenia pożarowe i środowiskowe podczas obchodzenia się z paliwem wymagają odpowiednich środków ochronnych."],"b-laufwerk":["Dlaczego należy regularnie sprawdzać gąsienice i podwozie?","Podczas jazdy zauważasz nietypowe wibracje.","Aby maszyna mogła poruszać się szybciej.","Ponieważ uszkodzenia mogą mieć wpływ na bezpieczne prowadzenie i stabilność.","Ponieważ praca jest zawsze dozwolona bez kontroli wzrokowej.","Uszkodzenie napędu może mieć wpływ na zwrotność, stabilność i bezpieczeństwo pracy."],"b-einweisen":["Co jest wymagane podczas pracy w pobliżu publicznego ruchu pieszego?","Koparka pracuje bezpośrednio na krawędzi chodnika.","Piesi powinni sami poruszać się po obszarze huśtawki.","Wystarczy przykleić znak na łopacie.","Skutecznie odgrodzij obszar zagrożenia i bezpiecznie kieruj ruchem.","Osoby trzecie nie mogą wchodzić do strefy zagrożenia maszyn do robót ziemnych; Niezbędne są odpowiednie bariery i organizacja ruchu."],"g2-fahrweg":["Na drodze przed nami rozlany jest płyn. Jak sobie z tym radzisz?","Wózek widłowy przejechałby bezpośrednio po śliskim terenie.","Zatrzymaj jazdę i zabezpiecz lub usuń niebezpieczne miejsce.","Przejedź miejsce tak szybko, jak to możliwe, z podniesionymi widłami.","Mam nadzieję na suchsze opony i dalszą jazdę bez zmian.","Zanieczyszczone trasy zagrażają stabilności i należy je odpowiednio zabezpieczyć przed wjazdem."],"g2-sichtladung":["Wysoka paleta zasłania widok przed sobą. Co jest słuszne?","Musisz jechać do magazynu i nie widzisz trasy.","Podnieś paletę do góry, aż będzie widać jej spód.","Jedź wyłącznie odpowiednimi, bezpiecznymi metodami, takimi jak cofanie przy dobrej widoczności.","Nadal możesz jechać po drodze bez drogowskazu i dobrej widoczności.","Kierunek jazdy i widoczność muszą umożliwiać bezpieczną obserwację trasy ruchu; Ładunki nie mogą zastępować kontroli wzrokowej."],"g2-fussgaengerstop":["Pieszy zatrzymuje się tuż obok wózka widłowego. Co robisz?","Osoba znajduje się w możliwym zasięgu jazdy i obrotu.","Wyprzedź pieszego, lekko przyspieszając.","Przejedź obok osoby z podniesionym ładunkiem.","Zatrzymaj się i kontynuuj jazdę tylko w bezpiecznej odległości.","Ludzie muszą trzymać się z dala od strefy zagrożenia; W razie potrzeby podróż należy przerwać."],"g2-hubmast":["Zauważasz uszkodzoną linię hydrauliczną na maszcie podnośnika. Co ma zastosowanie?","Z narzędzia wyraźnie wycieka olej hydrauliczny.","Wycofaj wózek widłowy z eksploatacji i zgłoś uszkodzenie.","Sprawdź szczelność ręcznie podczas podnoszenia.","Podnoś mniejsze ładunki tylko do zakończenia zmiany.","Uszkodzenia hydrauliczne mogą prowadzić do niekontrolowanych ruchów; bezpieczeństwo użytkowania nie jest gwarantowane aż do czasu przeprowadzenia testu."],"g2-lagerregal":["Chcesz przechowywać paletę na półce. Co sprawdzasz w pierwszej kolejności?","Poziom półki jest wysoki i należy zachować nośność.","Jak najszybciej wsuń paletę na półkę.","Sprawdź, czy przedział półki, ciężar ładunku i wolna przestrzeń do przechowywania są odpowiednie.","Oszacuj całkowitą wagę wyłącznie na podstawie liczby pudełek.","Półki i sprzęt do przenoszenia ładunku muszą być dostosowane do ładunku i sytuacji przechowywania."],"g2-batterieschaden":["Akumulator wózka widłowego jest uszkodzony zewnętrznie. Co jest słuszne?","Przed załadunkiem zauważa się pęknięcia lub nietypowy płyn.","Zakryj uszkodzenia taśmą klejącą i natychmiast załaduj.","Pozwól innej osobie naładować akumulator bez sprawdzania.","Nie ładuj ani nie używaj i poinformuj o tym odpowiedzialnych specjalistów.","Uszkodzone akumulatory stwarzają zagrożenie elektryczne i chemiczne i wymagają profesjonalnej oceny."],"g2-fahrerkabine":["Co dotyczy luźnych przedmiotów w obszarze kierowcy?","Narzędzia leżą na podłodze obok pedałów sterujących.","Usuń przedmioty i utrzymuj obszar operacyjny w czystości.","Podczas jazdy trzymaj narzędzie tylko jedną nogą.","Ukryj luźne części pod siedzeniem kierowcy.","Luźne przedmioty mogą blokować pedały i utrudniać bezpieczną obsługę pojazdu."],"g2-uebergabe":["Po zmianie zmiany przejmujesz wózek widłowy. Co to obejmuje?","Kolega ostatnio korzystał z pojazdu.","Załóżmy, że kolega przejął wszystkie kontrole.","Przeprowadź niezbędną kontrolę i zapytaj o znane usterki.","Rozpocznij podróż bez patrzenia na maszynę.","Osoba przejmująca musi przed użyciem upewnić się, że jest ona w bezpiecznym stanie."],"g2-transportsicherung":["Na palecie leży luzem wysoki przedmiot. Jak się zachowujesz?","Podczas hamowania ładunek może przechylić się do przodu.","Widły należy przenosić szczególnie wysoko, aby ładunek pozostawał stabilny.","Po prostu pokonuj zakręty powoli, jedź szybciej prosto.","Ustaw ładunek stabilnie i zabezpiecz go przed przewróceniem lub upadkiem.","Luźne ładunki należy przed transportem ustabilizować, aby ruchy hamowania i jazdy nie spowodowały ich upadku."],"g2-arbeitsende":["Co jest ważne w przypadku wózka widłowego bez nadzoru?","Kończysz swoją zmianę i opuszczasz teren.","Zaparkuj pojazd bezpiecznie i zabezpiecz go przed stoczeniem się i nieuprawnionym użyciem.","Zostaw kluczyk, aby współpracownicy mogli znaleźć maszynę.","Widelec zostaw na wysokości oczu, tak aby był widoczny.","Bezpieczne parkowanie obejmuje obsługę opuszczonego ładunku oraz ochronę przed ruchem i nieupoważnionym uruchomieniem."],"g2-bremsweg":["Dlaczego należy zwracać szczególną uwagę na drogę hamowania pod obciążeniem?","Wózek widłowy transportuje ciężkie towary przez korytarz magazynu.","Zawsze hamuj później z większym ładunkiem niż bez ładunku.","Dostosuj prędkość do widoczności, warunków podłoża i obciążenia.","Podczas hamowania należy gwałtownie podnieść ładunek, aby lepiej hamować.","Masa i stan nawierzchni wpływają na drogę hamowania; dostosowana prędkość ma kluczowe znaczenie."],"g2-rampe":["Co sprawdzasz przed wejściem na stromą rampę?","Trasa może być zbyt stroma dla pojazdu.","Wjedź na rampę z maksymalną prędkością, niezależnie od nachylenia.","Przejedź przez krawędź rampy z podniesionym ładunkiem.","Sprawdź dopuszczalne nachylenie i bezpieczny tryb pracy na podstawie specyfikacji pojazdu.","Można korzystać wyłącznie z ramp mieszczących się w przewidzianych granicach eksploatacyjnych; Decydujące znaczenie mają instrukcje obsługi i kontrola obciążenia."],"g2-zinke":["Paleta jest szersza niż odległość wideł. Co należy wziąć pod uwagę?","Planujesz wziąć na siebie niezwykle duży ładunek.","Dopasuj rozstaw wideł i punkty mocowania do obciążenia.","Jeśli ładunek jest zbyt szeroki, należy używać tylko jednego zęba.","Podnieś ładunek pod kątem, aż osiągnie prawidłowe położenie.","Równomierne i odpowiednie pochłanianie obciążenia zmniejsza poślizg i przewrócenie."],"g2-betriebsanweisung":["Jaką rolę pełni eksploatacyjna regulacja ruchu?","Na terenie magazynu obowiązują oznaczone obszary jednokierunkowe i piesze.","W przypadku wózków widłowych obowiązują wyłącznie przepisy ruchu drogowego.","Postępuj zgodnie z określonymi trasami i zasadami ruchu drogowego.","Po załadowaniu pojazdu należy ignorować oznaczenia.","Trasy firmowe i zasady bezpieczeństwa chronią ruch wózków widłowych i osoby poruszające się pieszo."],"g2-nothalt":["Układ kierowniczy reaguje nietypowo podczas jazdy. Co jest słuszne?","Pojazdem nie można już normalnie sterować.","Jedź z większą prędkością, aby układ kierowniczy czuł się lepiej.","Kompensuj błąd przy szczególnie dużych odchyleniach kierownicy.","Zatrzymaj się w bezpiecznym miejscu i oddaj pojazd do sprawdzenia.","Upośledzone sterowanie zagraża bezpiecznemu prowadzeniu; maszyny nie wolno dalej używać w sposób niekontrolowany."],"g2-anschlagkette":["Chcesz przenieść swobodnie wiszący ładunek za pomocą wózka widłowego. Co ma zastosowanie?","Ładunek powinien wisieć na haku pod widłami.","Tylko z zatwierdzonym urządzeniem i odpowiednim sprzętem do przenoszenia ładunku.","Każdy łańcuch będzie odpowiedni, jeśli ładunek nie jest ciężki.","Zacisnąć łańcuch bezpośrednio pomiędzy obydwoma widłami.","Swobodnie wiszące ładunki zmieniają stabilność; Wymagane są atesty producenta i odpowiednie urządzenia."],"g2-rollenlast":["Element cylindryczny leży niezabezpieczony na palecie. Co robisz?","Ładunek może się przewrócić podczas transportu.","Podejdź do palety szczególnie gwałtownie.","Przed podniesieniem palety element należy zabezpieczyć przed przetoczeniem.","Umieścić zęby na tyle wysoko, aby element nie był widoczny.","Ładunki okrągłe lub toczące się wymagają niezawodnej ochrony przed zmianami położenia."],"g2-pruefplakette":["Skąd wiadomo, czy wózek widłowy nadaje się do użytku?","Na maszynie przyklejona jest naklejka kontrolna.","Każda naklejka zawsze zastępuje codzienną kontrolę wzrokową.","Brak luzu można zastąpić ostrożną jazdą.","Oprócz sprawdzenia pojazdu należy wziąć pod uwagę ważny status badań i zezwolenie na użytkowanie.","Powtarzające się testy i codzienne kontrole operacyjne spełniają różne funkcje bezpieczeństwa."],"g2-licht":["Oświetlenie w magazynie nagle zgasło. Co jest słuszne?","Nie możesz już bezpiecznie widzieć przeszkód na ścieżce.","Zatrzymaj jazdę do czasu zapewnienia bezpiecznej widoczności.","Zwiększ prędkość jazdy, aby opuścić ciemny obszar.","Kontynuuj jazdę z podniesionymi widłami bez kontroli wzrokowej.","Trasą, której nie można bezpiecznie przeoczyć, nie można pokonywać bez skutecznych środków bezpieczeństwa."],"g2-ueberhang":["Ładunek wystaje daleko poza bok wideł. Co sprawdzasz?","Chcesz przewieźć paletę przez wąską bramę.","Kompensuj projekcję boczną za pomocą szybkiego zakrzywienia.","Przed jazdą należy ocenić prześwit, stabilność i dopuszczalną nośność.","Prowadź ładunek z maksymalną prędkością, niezależnie od jego kształtu.","Zwisy zwiększają ryzyko kolizji i mogą zmieniać stabilność oraz wymaganą przestrzeń do ruchu."],"g2-wartungsbereich":["Przed obszarem konserwacji znajdują się bariery. Jak się zachowujesz?","Twoja zwykła trasa jest tymczasowo zamknięta.","Przesuń na chwilę bariery i przejedź niezauważony.","Przejedź bezpośrednio przez obszar roboczy pod obciążeniem.","Obserwuj zamknięcie i wybierz zatwierdzoną alternatywną trasę.","Do obszarów odgrodzonych nie można wjeżdżać ani przejeżdżać bez pozwolenia."],"g2-bremsprobe":["Kiedy test funkcjonalny hamulca głównego ma sens?","Przygotowujesz wózek widłowy przed pracą.","W ramach wymaganej kontroli przed użyciem.","Wykonywać wyłącznie po poważnym wypadku.","Tylko jeśli ciężarówka osiągnęła już dużą prędkość.","Przed użyciem sprawdza się funkcjonalność urządzeń istotnych dla bezpieczeństwa."],"g2-fahrzeuganhaenger":["Chcesz ciągnąć przyczepę za pomocą wózka widłowego. Co jest wymagane?","Firma planuje transport z dołączonym ładunkiem.","Przywiąż każdą przyczepę do wideł bez sprawdzania.","Należy przestrzegać dopuszczenia producenta, odpowiedniego sprzęgła i dopuszczalnego obciążenia rozciągającego.","Po prostu zwiększ ciśnienie w oponach i ruszaj.","Eksploatacja pociągu jest możliwa wyłącznie w ramach specyfikacji technicznych i przy odpowiednim połączeniu."],"g2-rueckfahrt":["Co jest ważne podczas cofania wózkiem widłowym?","W korytarzu magazynu panuje zamieszanie.","Zawsze patrz tylko w lusterko wsteczne, niezależnie od otoczenia.","Jedź bez widoczności, dopóki klakson został naciśnięty raz.","Bezpiecznie obserwuj trasę i obszar przebywania ludzi iw razie potrzeby poinstruuj ich.","Cofanie wymaga dobrej widoczności lub skutecznych dodatkowych środków bezpieczeństwa."],"g2-lastentnahme":["Z wysokiej półki wyjmujesz paletę. Co jest słuszne?","Paleta może nie być wyśrodkowana.","Podnieś bezpiecznie ładunek i ustabilizuj go przed opuszczeniem.","Pozwól, aby paleta przechyliła się na bok podczas jej wyciągania.","Sprawdź pod podniesioną paletą, czy nie jest uszkodzona.","Kontrolowane podnoszenie i opuszczanie zapobiega spadaniu ładunków i niebezpiecznym ruchom."],"h2-absenkweg":["Dlaczego przestrzeń pod platformą roboczą musi pozostać wolna?","Kosz zostaje opuszczony, a pod nim umieszczane są materiały.","Dociśnij materiały za pomocą kosza.","Należy zwracać uwagę wyłącznie na obszar stóp operatora.","Podczas opuszczania należy unikać ryzyka zmiażdżenia i kolizji.","W obszarze opuszczania nie mogą znajdować się żadne osoby ani przeszkody, które mogłyby zostać uwięzione."],"h2-transporthoehe":["Jak przenieść mobilną scenę nad niskim przejściem?","Prześwit jest mniejszy niż w przypadku wysuniętego wysięgnika.","Ustaw platformę w odpowiedniej pozycji transportowej zgodnie z instrukcją obsługi.","Pozostaw wysięgnik wysunięty i przesuwaj się pod sufitem.","Dociśnij kosz do boku ościeżnicy.","W przypadku ruchów jezdnych wysokość całkowita i pozycja transportowa muszą być zgodne ze specyfikacjami producenta i przejazdem."],"h2-bodenoeffnung":["W podłodze obok sceny znajduje się niezabezpieczony otwór. Jak reagujesz?","W pobliżu otworu znajduje się punkt jazdy lub wsparcia.","Umieść podporę bezpośrednio na krawędzi otworu.","Zmień miejsce montażu lub zleć profesjonalne sprawdzenie nośności i zabezpieczenia.","Miejsce zagrożenia przykryj wyłącznie kartonem.","Otwory i obszary krawędziowe mogą ulec uszkodzeniu pod obciążeniem podporowym i należy je skutecznie uwzględnić."],"h2-rettungsperson":["Dlaczego druga osoba musi znać procedurę ratunkową?","Na górze operator może stracić zdolność do pracy.","Aby praca w koszu mogła w zasadzie odbywać się bez zabezpieczeń.","Aby scena mogła działać szybciej niż jest to dozwolone.","Aby w sytuacji awaryjnej można było rozpocząć bezpieczną akcję ratowniczą.","Koncepcja ratunkowa musi uwzględniać pomoc naziemną w przypadku awarii lub sytuacji awaryjnej."],"h2-werkzeugabwurf":["Co dotyczy narzędzi na dużych wysokościach?","Luźne narzędzie może spaść z krawędzi kosza.","Narzędzia należy zabezpieczyć tak, aby nie stanowiły dla nikogo zagrożenia ani nie spadły.","Aby zmniejszyć obciążenie, wystarczy umieścić narzędzia na poręczy.","W razie potrzeby wyrzuć narzędzia z kosza.","Spadające przedmioty stanowią zagrożenie dla ludzi poniżej; Materiał należy bezpiecznie przechowywać."],"h2-trittstufe":["Pudełko powinno służyć jako dodatkowe miejsce stojące w koszyku. Co jest słuszne?","W przeciwnym razie ledwo dotrzesz do miejsca pracy.","Połóż skrzynkę na poręczy i wdrap się na nią.","Nie wspinaj się na prowizoryczne wzniesienia; Używaj odpowiedniego sprzętu roboczego.","Celowo załaduj kosz powyżej dozwolonej wysokości.","Improwizowane podwyższenia pogarszają zamierzoną ochronę przed upadkiem i są niedozwolone."],"h2-lastverteilen":["Na co zwracasz uwagę, gdy w koszyku pracy znajduje się kilka osób?","Dwie osoby pracują w koszu ciężkimi narzędziami.","Oceniaj obciążenie wyłącznie na podstawie rozmiaru narzędzia.","Ciężkie narzędzia przechowuj bezpośrednio na poręczy ochronnej.","Nie przekraczać dopuszczalnego obciążenia kosza, łącznie z ludźmi i narzędziami.","Dopuszczalna ładowność obejmuje wszystkie osoby, materiały i narzędzia znajdujące się w koszu."],"h2-abstuetzplatte":["Kiedy rozważane są dodatkowe podkładki podkładkowe dla podpór?","Podłoga instalacyjna może wytrzymać jedynie ograniczone obciążenie.","Jeżeli jest to konieczne dla bezpiecznego rozłożenia obciążenia zgodnie ze specyfikacjami.","W celu umieszczenia podpór jak najbliżej krawędzi wykopu budowlanego.","Aby użyć większego zasięgu bez informacji producenta.","Aby zapewnić bezpieczne działanie sił podporowych, wymagane są wystarczające powierzchnie styku."],"h2-baugrube":["Scena powinna być usytuowana bezpośrednio przy krawędzi wykopu budowlanego. Co sprawdzasz?","Podglebie może ustąpić na boki w wyniku wykopu.","Wsunąć podpory do wykopu.","Należy zapewnić wystarczający odstęp bezpieczeństwa i nośność podłoża.","Ryzyko kompensuj jedynie poprzez powolne podnoszenie kosza.","Wykopy mogą wpływać na stabilność ze względu na uszkodzenia zboczy i podłoża."],"h2-witterung":["Podczas użytkowania tworzy się lukier. Jak się zachowujesz?","Powierzchnie sterujące i obszar roboczy stają się gładkie.","Podnieś scenę, aby uniknąć śniegu i lodu.","Ignoruj ​​ostrzeżenia, dopóki platforma jest oświetlona.","Przerwać pracę i ponownie ocenić warunki pracy zgodnie z instrukcją obsługi.","Zmiany pogody mogą zmienić odpowiedzialność, funkcjonalność i bezpieczne granice użytkowania."],"h2-aufbaukontakt":["Stalowa konstrukcja ogranicza ścieżkę kosza. Co jest ważne?","Podczas podnoszenia istnieje ryzyko zmiażdżenia pomiędzy koszem a nośnikiem.","Zaplanuj ruchy tak, aby Twoje ciało i koszyk nie zostały uwięzione.","Spraw, aby podróż była szybsza, aby kosz przeminął szybciej.","Przesuń konstrukcję z koszem na bok.","Punkty ucisku pomiędzy platformą a otoczeniem wymagają uważnej obserwacji i kontrolowanego ruchu."],"h2-sicherheitsabstand":["Kiedy należy odgrodzić niebezpieczną strefę sceny?","Pod działką przebiega trasa komunikacji miejskiej.","Tylko jeśli obiekt już spadł.","Jeżeli ruch lub spadające przedmioty mogłyby zagrozić osobom trzecim.","Nigdy, ponieważ kosz roboczy w zasadzie zapobiega wszelkim niebezpieczeństwom.","Teren pod sceną i obok niej należy zabezpieczyć przed przewidywalnymi zagrożeniami."],"h2-korbtor":["Co dotyczy drzwi wejściowych do kosza roboczego?","Jesteś już na wysokości roboczej.","Zostaw drzwi otwarte, żeby móc szybciej wyjść.","Zawiąż drzwi na stałe otwarte liną.","Trzymaj drzwi zamknięte zgodnie z dostarczonym mechanizmem blokującym.","Dostarczone blokady stanowią część zabezpieczeń przed wypadnięciem z kosza roboczego."],"h2-energieleitung":["Co ma zastosowanie, jeśli linia napowietrzna nie jest bezpiecznie wyłączona?","Pracujesz z platformą roboczą w pobliżu nich.","Należy zachować określone odległości bezpieczeństwa i niezbędne środki ochronne.","Przesuwaj kosz tuż przed linią, dopóki go nie dotkniesz.","Zaufaj plastikowym oponom i pracuj bez przerw.","Przeskoki elektryczne są również możliwe bez bezpośredniego kontaktu; Wymagane są bezpieczne odległości."],"h2-schwanken":["Kosz roboczy zaczyna się niezwykle mocno kołysać. Co jest słuszne?","Ruch nie jest już kontrolowany.","Dostosuj się w sposób niekontrolowany, wykonując szybkie kontrataki.","Zatrzymaj ruch i sprawdź przyczynę lub warunki pracy.","Dodaj dodatkowe osoby do koszyka, aby był cięższy.","Nietypowe wibracje mogą wskazywać na nieodpowiednie warunki pracy lub awarię."],"h2-ladegeraet":["Kabel ładujący stopnia sterowanego elektrycznie jest uszkodzony. Co robisz?","Podczas podłączania widoczna jest uszkodzona izolacja.","Dotknij uszkodzenia mokrymi rękawiczkami.","Wciśnij wtyczkę do gniazdka tak mocno, jak to możliwe.","Nie rozpoczynaj procesu ładowania i oddaj kabel do profesjonalnego sprawdzenia.","Uszkodzone przewody elektryczne stwarzają ryzyko porażenia prądem elektrycznym i pożaru."],"h2-gelaenderanbau":["Czy możesz sam usunąć poręcz, aby podejść bliżej?","Element uniemożliwia ludziom zbliżanie się do miejsca pracy.","Nie modyfikuj ani nie usuwaj samodzielnie urządzeń ochronnych.","Po podniesieniu należy odkręcić balustradę i zamontować ją później.","Kontynuuj pracę bez poręczy, dopóki ktoś stoi obok niej.","Nie wolno zmieniać konstrukcyjnych urządzeń ochronnych bez dozwolonych specyfikacji i bezpiecznych środków zastępczych."],"h2-lastkran":["Czy platformę można wykorzystać jako dźwig do podnoszenia ładunku?","Materiał należy transportować wiszący swobodnie obok kosza roboczego.","Zawsze, gdy waga jest mniejsza niż masa własnego ciała.","Tylko wtedy, gdy producent i urządzenie wyraźnie zezwalają na to specjalne zastosowanie.","Wystarczy przymocować hak do poręczy i podnieść materiał.","Podesty ruchome nie są automatycznie przystosowane do pracy dźwigiem lub dodatkowych wiszących ładunków."],"h2-arbeitsvorbereitung":["Co wiąże się z przygotowaniami do nowej lokalizacji?","Nie znasz jeszcze placu budowy.","Wystarczy oszacować odległość do najbliższego parkingu.","Niezależnie od otoczenia, natychmiast rozciągnij go całkowicie.","Oceń zagrożenia, glebę, trasy ruchu, akcję ratunkową i przydatność sprzętu.","Ocena ryzyka związana z lokalizacją jest warunkiem wstępnym bezpiecznych warunków pracy."],"h2-kabelschlaufe":["Kabel zasilający przebiega wzdłuż ścieżki sceny. Co jest słuszne?","Kabel może zostać uwięziony podczas ruchu.","Oczyść drogę i chroń kable elektryczne przed uszkodzeniem.","Użyj linki z kołami jako progu drogowego.","Podnieś kosz, nie sprawdzając powierzchni podłogi.","Przejechane lub zgniecione kable mogą powodować zagrożenia elektryczne i mechaniczne."],"h2-leitungsnaehe":["Kto wyjaśnia środki ochronne w systemie elektrycznym?","Platforma powinna pracować blisko sprzętu pod napięciem.","Osoba w koszyku decyduje wyłącznie na podstawie wzroku.","Zaangażuj odpowiedzialne władze i wprowadź skoordynowane środki ochronne.","Odległość zostanie ustalona dopiero po rozpoczęciu prac.","Praca w pobliżu instalacji elektrycznych wymaga zaplanowanych i skoordynowanych środków ochronnych."],"h2-funkkommunikation":["Dlaczego sygnały między podłogą a koszem muszą być wyraźne?","Osoba na ziemi pomaga w manewrowaniu.","Aby kilka osób mogło jednocześnie wydawać sprzeczne instrukcje.","Aby można było wypróbować opuszczanie awaryjne bez instrukcji.","Aby ruchy były wykonywane tylko po jasnej komunikacji.","Przejrzysta komunikacja ogranicza nieprawidłowe ruchy i kolizje podczas manewrowania."],"h2-neuebedienung":["Przechodzisz na inny typ sceny. Co jest wymagane?","Funkcje operacyjne różnią się znacznie.","Instrukcja dotycząca konkretnego urządzenia przed samodzielnym użyciem.","Wystarczy odczytać logo firmy na urządzeniu.","Jazda próbna z już wysuniętym koszem bez instrukcji.","Sama kwalifikacja nie zastępuje szkolenia w zakresie konkretnego typu urządzenia."],"h2-steckanschluss":["Co należy sprawdzić przed podłączeniem ładowarki?","Elektryczny podnośnik koszowy wymaga ładowania.","Użyj dowolnego gniazdka, niezależnie od stanu i bezpiecznika.","Sprawdź odpowiednie połączenie i nieuszkodzony kabel zgodnie z instrukcją producenta.","Podczas ładowania należy regularnie odłączać wtyczkę zasilania.","Odpowiednie i nienaruszone połączenia elektryczne chronią przed porażeniem prądem elektrycznym i pożarem."],"h2-absperrpersonal":["Podczas podnoszenia osoba wchodzi na odgrodzony obszar. Co robisz?","Bezpośrednio pod koszem roboczym widać osobę.","Kontynuuj jazdę, jeśli osoba ma na sobie kask ochronny.","Upuść narzędzie w ich kierunku jako sygnał ostrzegawczy.","Zatrzymaj niebezpieczny ruch i oczyść teren.","Szlaban nie zastępuje obserwacji strefy niebezpiecznej w trakcie pracy."],"k2-arbeitsplanung":["Co należy uwzględnić w przygotowaniu pracy przed operacją dźwigu?","Ładunek, lokalizacja i trasa transportu nie zostały jeszcze uzgodnione.","Najpierw podnieś najcięższy ładunek bez dalszego planowania.","Zaznaczaj tylko najkrótszą trasę na podłodze hali.","Należy wcześniej określić nośność, zawiesia, drogę ładunku i obszar niebezpieczny.","Planowany ruch dźwigu wymaga odpowiedniej obsługi ładunku, bezpiecznych tras i skoordynowanych środków ochronnych."],"k2-hakenposition":["W jaki sposób hak dźwigu jest ustawiony nad ładunkiem przed podniesieniem?","Punkty mocowania znajdują się poniżej żurawia.","Jak najbardziej pionowo nad środkiem ciężkości, zgodnie z ogranicznikiem.","Przesuń daleko w bok, aby ładunek przesuwał się szybciej.","W każdym razie na zewnętrznej krawędzi ładunku, niezależnie od środka ciężkości.","Pionowe przyłożenie siły i odpowiednie punkty kotwiczenia ograniczają ruchy boczne i niekontrolowane ruchy."],"k2-hakengabel":["Hak ładunkowy wykazuje zauważalne odkształcenie. Co ma zastosowanie?","Hak wygląda na wygięty w porównaniu ze swoim zwykłym stanem.","Odegnij odkształcenie z powrotem przy następnym obciążeniu.","Zatrzymaj pracę dźwigu i zleć sprawdzenie haka specjaliście.","Dołączaj tylko lekkie ładunki i kontynuuj pracę.","Odkształcenie może mieć wpływ na bezpieczeństwo haka; Dalsze nieuprawnione użycie jest niedozwolone."],"k2-zugueberlast":["Obciążenie jest większe, niż początkowo zakładano. Co robisz?","Podczas przygotowywania pojawiają się nowe informacje o wadze.","Wymień rezerwę bezpieczeństwa na szybsze podnoszenie.","Zignoruj ​​ciężar ładunku, mocując go w innym punkcie.","Określ rzeczywiste obciążenie i ponownie sprawdź limity obciążenia.","Bezpieczne podnoszenie wymaga wiarygodnych danych dotyczących obciążenia i przestrzegania wszystkich odpowiednich udźwigów."],"k2-arbeitskorb":["Czy zwykły hak dźwigowy może z łatwością transportować ludzi?","Osoba chce dostać się na wysokie miejsce pracy.","Nie, transport pasażerski wymaga dozwolonych specjalnych udogodnień i środków.","Tak, jeśli osoba trzyma się liny procy.","Tak, gdy tylko udar zostanie przeprowadzony szczególnie powoli.","Przewóz osób dozwolony jest wyłącznie na specjalnych warunkach przewidzianych w tym celu."],"k2-bruecke":["Żuraw mostowy porusza się po wspólnej ścieżce hali. Co jest ważne?","Pracownicy pozostają pod trasą transportu.","Jedź z ładunkiem tuż nad głowami pracowników.","Skutecznie utrzymuj trasę ładunku i obszar ruchu w czystości i bezpieczeństwie.","Zamiast dalszych środków stosować wyłącznie klakson ostrzegawczy.","Osoby zagrożone nie mogą znajdować się pod zawieszonymi ładunkami ani na trasie transportu."],"k2-zweitekrane":["Dwa dźwigi pracują na nakładającym się obszarze. Co jest konieczne?","Wysięgniki lub ładunki mogą się ze sobą zderzyć.","Obaj operatorzy dźwigów pracują w tym samym czasie bez wcześniejszego porozumienia.","Ruchy są celowo przyspieszane, aby uniknąć skrzyżowań.","Koordynuj działania i podejmuj odpowiednie działania, aby zapobiec wzajemnym zagrożeniom.","Nakładające się obszary pracy wymagają skoordynowanej organizacji operacyjnej i odpowiednich zabezpieczeń."],"k2-pruefbuch":["Jakie znaczenie ma obowiązkowy okresowy przegląd dźwigu?","Maszyna jest regularnie używana w operacjach.","Uzupełnia kontrolę operacyjną o wymagane badania eksperckie.","Zastępuje na stałe wszelkie oględziny przed rozpoczęciem pracy.","Jest to wymagane tylko po awarii.","Inspekcje okresowe i bieżące kontrole operacyjne mają różne zadania."],"k2-absetzflaeche":["Planowany obszar umieszczenia jest nierówny. Jak się zachowujesz?","Ładunek może się przewrócić po umieszczeniu.","Umieść ładunek w jednym rogu i pozwól mu wisieć bez zmian.","Przygotuj odpowiednie, nośne i stabilne podłoża lub powierzchnie.","Podczas opuszczania umieść jedną osobę pod ładunkiem.","Obszary umieszczenia muszą bezpiecznie podtrzymywać ładunek i zapobiegać niebezpiecznym przechyleniom lub przetaczaniu się."],"k2-anfahrbereich":["Zanim dźwig zacznie się poruszać, w strefie przejazdu znajduje się jedna osoba. Co robisz?","Trasa jest zablokowana przez osobę.","Odepchnij tę osobę na bok podczas krótkiej jazdy próbnej.","Ruszaj, korzystając wyłącznie z wyłącznika krańcowego, bez kontroli wzrokowej.","Rozpocznij ruch dopiero wtedy, gdy obszar zagrożenia jest czysty i bezpieczny.","Ruchy jezdne i obrotowe nie mogą stwarzać zagrożenia dla ludzi."],"k2-schlaffseil":["Dlaczego lina wciągnika nie powinna zwisać w niekontrolowany sposób podczas opuszczania?","Ładunek jest włączony, hak jest bardziej opuszczony.","Aby lina i haki nie uległy zakleszczeniu i niekontrolowanemu obciążeniu.","Aby ładunek mógł być następnie ciągnięty bocznie przez linę.","Tak, aby zawiesia odczepiły się od haka.","Niekontrolowane prowadzenie kabli może prowadzić do splątań i niebezpiecznych ruchów ładunku."],"k2-pendel":["Transportowany ładunek zaczyna się kołysać. Co jest słuszne?","Ładunek przesuwa się w bok bardziej niż planowano.","Kompensuj to szybkimi kontratakami i pełną prędkością.","Ogranicz ruchy w kontrolowany sposób i uspokój dojazdy bez osób znajdujących się w strefie zagrożenia.","Trzymaj wahadłowy ładunek gołymi rękami.","Obciążenia oscylacyjne mogą mieć wpływ na ludzi i obiekty; spokojne ruchy zmniejszają ryzyko."],"k2-funkakku":["Sterowanie radiowe dźwigu ma słabą baterię. Co ma zastosowanie?","Połączenie może zostać przerwane podczas podnoszenia.","Szybko podnieś ładunek, zanim nastąpi awaria sterowania.","Jeżeli połączenie zostanie utracone, przesuń ładunek, ciągnąc za pas.","Przed użyciem należy zapewnić niezawodne połączenie sterujące.","Niezawodne sterowanie i komunikacja są warunkami wstępnymi kontrolowanych ruchów żurawia."],"k2-mehrereanschlaeger":["Dwie osoby jednocześnie dają operatorowi dźwigu różne sygnały. Co jest słuszne?","Znaki są ze sobą sprzeczne.","Przerwij ruch i wyjaśnij wyraźnie, jaka jest odpowiedzialność.","Preferuj znak osoby znajdującej się dalej.","Kontynuuj ruch zgodnie z własnym odczuciem.","Kierowcy dźwigów potrzebują jasnej i jednoznacznej komunikacji, zwłaszcza gdy trasy ładunku są zagmatwane."],"k2-endabschaltung":["Dlaczego wyłącznik krańcowy nie powinien być nadużywany jako normalne ograniczenie skoku?","Ładunek jest często przesuwany na maksymalną odległość podnoszenia.","Wyłączniki krańcowe zazwyczaj umożliwiają szybsze podnoszenie bez widoczności.","Wyłączniki krańcowe są urządzeniami zabezpieczającymi i nie zastępują kontrolowanego działania.","Powinny być uderzane tak mocno, jak to możliwe przy każdym uderzeniu.","Urządzenia zabezpieczające służą ochronie przed zagrożeniami i nie wolno ich nadużywać zgodnie z przeznaczeniem."],"k2-wetterbeobachtung":["Przy dużym obciążeniu powierzchniowym wiatr znacznie wzrasta. Co jest wymagane?","Duży obszar komponentów działa jak żagiel.","Zawsze podnoś ładunek wyżej, aby wiatr miał mniejszy wpływ.","Wymień chusty na cieńsze.","Oceń ograniczenia wiatrowe i operacyjne i w razie potrzeby dostosuj podnoszenie.","Wiatr może generować znaczne dodatkowe siły i ruchy wahadłowe, zwłaszcza przy obciążeniach wielkopowierzchniowych."],"k2-ortswechsel":["Co jest ważne przy przenoszeniu dźwigu samojezdnego w nowe miejsce?","Zmieniają się warunki podłoża i podłoża.","Przed ponownym podniesieniem ładunku sprawdź położenie stojaka i podparcie.","Zastosuj ustawienia z poprzedniej lokalizacji bez sprawdzania.","Podczas podnoszenia należy ponownie wyregulować podporę.","Każde miejsce instalacji może charakteryzować się innymi warunkami obciążenia podłoża i podpór."],"k2-betriebsbereich":["Dźwig ma pracować po drugiej stronie ulicy. Co należy wyjaśnić?","Osoby trzecie mogą dostać się do strefy zagrożenia.","Zabezpieczaj drogę wyłącznie klaksonem ostrzegawczym.","Wymagane blokady, głosowania i środki ochrony przed hubem.","Podnieś ładunek nad pojazdem tak szybko, jak to możliwe, bez jego zabezpieczania.","Bezpieczne zarządzanie ruchem zapobiega niepotrzebnemu ryzyku dla osób trzecich w związku z ładunkami i ruchami dźwigów."],"k2-hochheben":["Po podniesieniu próbnym ładunek wisi wyraźnie krzywo. Co jest słuszne?","Najwyraźniej ostrość została źle oceniona.","Kontynuuj podnoszenie, aby nierównowaga sama się skorygowała.","Niech jedna osoba będzie ciągnąć ładunek pochylony.","Odłóż bezpiecznie ładunek i ponownie sprawdź osprzęt i środek ciężkości.","Podnośnik testowy służy do wykrywania nieprawidłowego zamocowania i niestabilnego położenia ładunku przed transportem."],"k2-schwebelast":["Czy możesz pozostawić podniesiony ładunek wiszący bez nadzoru?","Zmiana się kończy, ale ładunek nadal jest na haku.","Nie, bezpiecznie opuść ładunek i odpowiednio zabezpiecz dźwig.","Tak, jeśli żuraw jest zabezpieczony przed odsunięciem.","Tak, o ile na ziemi znajduje się znak ostrzegawczy.","Zasadniczo nie należy pozostawiać zawieszonych ładunków bez nadzoru."],"k2-mitnahme":["Kolega chce jechać na ładunku dźwigiem. Co ma zastosowanie?","Ładunek należy przewieźć na wyższy punkt.","Jazda jest dozwolona, ​​jeśli kolega ma na sobie kask.","Nie wolno przewozić osób na normalnych ładunkach ani przyłączać ich do nich.","Przejażdżka jest zawsze dozwolona, ​​jeśli współpracownik jest znany operatorowi dźwigu.","Przenoszenie ludzi wraz z ładunkami stwarza znaczne ryzyko upadku i zmiażdżenia."],"k2-warnsignal":["Awaria działającego systemu ostrzegania na dźwigu. Co jest słuszne?","Nie jest już możliwe ostrzeżenie przed rozpoczęciem jazdy.","Ignoruj ​​system, gdy silnik pracuje.","Wymień ostrzeżenie na stałe, dotykając obudowy.","Zgłoś awarię istotną dla bezpieczeństwa i przerwij działanie zgodnie z instrukcjami.","Wymagane urządzenia ostrzegawcze muszą działać, aby zapewnić ludziom ochronę w odpowiednim czasie."],"k2-schneekante":["Żuraw samojezdny wymaga podparcia na zmarzniętym, nierównym podłożu. Co ma zastosowanie?","W miarę rozmrażania gleba może stracić swoją nośność.","Oceń nośność i stan podparcia w rzeczywistych warunkach.","Zamarznięty grunt zawsze ma jakąkolwiek nośność.","Podpory umieszczaj wyłącznie na małych kamieniach.","Temperatura, wilgotność i struktura podłoża wpływają na nośność lokalizacji dźwigów."],"k2-laufkatze":["Wózek zbliża się do przeszkody. Jak się zachowujesz?","W obszarze jazdy znajduje się obiekt.","Powoli odepchnij przedmiot wraz z ładunkiem.","Zatrzymaj ruch w odpowiednim czasie i bezpiecznie usuń przeszkodę.","Przejedź obok przeszkody ze zwiększoną prędkością.","Ruchy żurawia należy prowadzić w taki sposób, aby nie doszło do kolizji z przeszkodami."],"k2-anschlagaufnahme":["Ładunek należy podnosić za pomocą niewyznaczonego oczka. Co jest słuszne?","Oczko mogło służyć jedynie do mocowania osłony.","Każde oczko jest przystosowane do pełnego obciążenia żurawia.","Obciążaj oczko tylko dwiema osobami jednocześnie.","Przed użyciem sprawdź nośność i przydatność punktu kotwiczącego.","Nie każde istniejące oczko jest stabilnym punktem mocowania ładunków dźwigowych."],"l2-seilbruch":["Lina stalowa pokazuje kilka zerwanych pojedynczych drutów. Co jest słuszne?","Punkty zerwania znajdują się w obszarze liny nośnej.","Nie używaj dalej sprzętu do podnoszenia i oddaj go do profesjonalnej oceny.","Odegnij końce drutu gołymi rękami.","Kontynuuj używanie liny, jeśli ładunek jest szczególnie lekki.","Przerwy w przewodach mogą stanowić kryterium odrzucenia; Uszkodzone liny należy poddać profesjonalnej ocenie."],"l2-schaekel":["Co jest istotne przy stosowaniu szekli?","Szekla łączy zawiesie i ładunek.","Wymień śrubę na dowolny gwóźdź.","Sprawdź, czy jest odpowiednia nośność, stan nieuszkodzony i czy śruby są prawidłowe.","Oszacuj nośność na podstawie koloru.","Szakle muszą mieć odpowiednie wymiary, być używane w całości i zgodnie z zamierzonym kierunkiem załadunku."],"l2-tragfaehigkeit":["O czym należy pamiętać, używając wielu pasm?","Pasma biegną pod kątem do pionu.","Po prostu dodaj nośność każdego pasma według potrzeb.","Zawieszaj ładunek tylko na najlżejszym pasie.","Należy uwzględnić nośność całego rodzaju kotwy i kątownika.","Kąt nachylenia i efektywna liczba splotów mają istotny wpływ na dopuszczalne obciążenie."],"l2-schweissnaht":["Czy improwizowany punkt kotwiczenia można przyspawać do ładunku?","Brak jest wyznaczonych odpowiednich punktów odbioru ładunku.","Należy używać wyłącznie prawidłowo zaprojektowanych i zatwierdzonych punktów kotwiczenia.","Dowolny szew spawalniczy jest wystarczający bez sprawdzania.","Włóż hak przez otwór w blasze.","Należy sprawdzić, czy punkty kotwiczące są odpowiednie dla sił występujących podczas podnoszenia."],"l2-einseitig":["Ładunek jest znacznie cięższy z jednej strony. Jak sobie z tym radzisz?","Środek ciężkości leży poza środkiem geometrycznym.","Pozostaw wszystkie pasma tej samej długości, niezależnie od środka ciężkości.","Określ środek ciężkości i odpowiednio dostosuj pozycję.","Najpierw podnieś ładunek na pełną wysokość podnoszenia.","Jeśli środek ciężkości nie jest wyśrodkowany, ładunek może nieoczekiwanie się przewrócić lub poszczególne sploty mogą zostać przeciążone."],"l2-kettenriss":["Co dotyczy zawiesia łańcuchowego z widocznymi pęknięciami?","Na jednym z ogniw łańcucha jest pęknięcie.","Zaznacz pęknięcie farbą i podnieś je bez zmian.","Owiń łącze drutem i użyj go ponownie.","Natychmiast zdjąć łańcuch i poinformować osobę odpowiedzialną.","Pęknięcia ogniw łańcucha nośnego są uszkodzeniami istotnymi dla bezpieczeństwa i wymagają wycofania z eksploatacji."],"l2-lastfuehrung":["Jak przewozić duży ładunek, gdy istnieje ryzyko rotacji?","Podczas podnoszenia ładunek może kołysać się na boki.","Należy stosować odpowiednie urządzenia naprowadzające i zachować bezpieczną odległość.","Podczas jazdy trzymaj ładunek bezpośrednio między rękami.","Wejdź pod ładunek i wyrównaj go od dołu.","Prowadzenie ładunku nie może powodować przedostania się rąk lub ciał do strefy niebezpiecznej."],"l2-schnueren":["Co jest ważne przy mocowaniu sznurowadeł?","Zawiesie jest prowadzone wokół elementu.","Załóż, że nośność jest taka sama jak w przypadku każdego innego rodzaju kotwy.","Należy zwrócić uwagę na przydatność rodzaju mocowania i dopuszczalne obciążenie zgodnie z oznaczeniem.","Ściągnąć zawiesie do oporu, bez sprawdzania.","Rodzaj mocowania sznurowania może zmienić dopuszczalną nośność i musi być używany prawidłowo."],"l2-winkelmesser":["Dlaczego nie można zignorować płaskiego kąta splotu?","Dwie liny zawiesi biegną niemal poziomo do ładunku.","Płaski kąt automatycznie wzmacnia pasmo.","Obciążenie jest zawsze rozłożone równomiernie, niezależnie od kąta.","Duże siły splotu mogą przekroczyć dopuszczalną nośność.","Wraz ze wzrostem kąta do pionu zwiększają się naprężenia w splotach."],"l2-heisse-last":["Co należy sprawdzić w przypadku gorącego obciążenia?","Część stalowa została niedawno poddana obróbce cieplnej.","Należy przestrzegać granicznych temperatur zawiesi i dokonać odpowiedniego doboru.","Każda chusta tekstylna jest w stanie wytrzymać każdą temperaturę.","Etykietowanie nie ma znaczenia, gdy jest gorąco.","Temperatura może mieć wpływ na dopuszczalną nośność zawiesi."],"l2-abstand":["Czy podczas odkładania można włożyć palce pod ładunek?","Ładunek powinien wylądować na powierzchni z milimetrową precyzją.","Tak, jeśli nosisz rękawice robocze.","Nie, zachowaj dystans i korzystaj z odpowiednich pomocy.","Tak, jeśli ruch żurawia jest szczególnie powolny.","Części ciała znajdujące się pomiędzy ładunkiem a podstawą mogą zostać uwięzione."],"l2-verbindung":["Ogniwo łączące łańcucha zawiesia nie jest zablokowane. Co ma zastosowanie?","Brakuje zapięcia.","Używaj rygla bez zamka, gdy nikt nie patrzy.","Uszczelnij element taśmą klejącą.","Nie uderzaj, dopóki element złączny nie zostanie prawidłowo zabezpieczony.","Elementy łączące należy zabezpieczyć całkowicie i zgodnie z ich konstrukcją."],"l2-lasthaken":["Co sprawdzasz zawieszając się na haku dźwigu?","Na hak należy wprowadzić kilka zawiesi.","Zapewnij bezpieczne dopasowanie i przydatność haków i zawieszenia.","Załóż zawiesia na końcówkę haka.","Zamień zamek hakowy na opaskę kablową.","Siłę należy przyłożyć zgodnie z przeznaczeniem w wyznaczonych obszarach."],"l2-fasern":["Pas do podnoszenia wykazuje silne szorstkowanie i uszkodzenie włókien. Co jest słuszne?","Włókna nośne są wyraźnie uszkodzone.","Zakryj uszkodzenie innym węzłem.","Odłącz pas do podnoszenia i zleć jego sprawdzenie specjaliście.","Następnie podnieś ładunek szybciej.","Uszkodzone włókna nośne mogą znacznie zmniejszyć nośność pasa podnoszącego."],"l2-anheben":["Co obowiązuje od razu po pierwszym centymetrze podnoszenia?","Ładunek właśnie podnosi się z podstawy.","Podciągnij ładunek na pełną wysokość bez kontroli.","Sprawdź pod obciążeniem, czy zawiesia są napięte.","Sprawdź położenie ogranicznika, równowagę i zachowanie podczas ruchu.","Kontrolowany podnośnik próbny uwidacznia ewentualne niestabilności przed dalszym transportem."],"l2-lastgewichte":["Masa ładunku nie jest znana. Co jest słuszne?","Element nie posiada oznaczenia masy.","Przed wyborem zawiesi określ nośną masę.","Oszacuj wagę na podstawie koloru ładunku.","Użyj dowolnej chusty o podwójnej długości.","Bez znanej lub wiarygodnie określonej masy nie można z całą pewnością sprawdzić przydatności zawiesi."],"l2-lose-teile":["Na ładunku, który ma zostać podniesiony, znajdują się luźne narzędzia. Co robisz?","Narzędzia mogą spaść podczas podnoszenia.","Podczas jazdy trzymaj narzędzia jedną ręką.","Przed podniesieniem usuń lub skutecznie zabezpiecz luźne przedmioty.","Podnoś ładunek nieco szybciej, aby nic się nie ześlizgnęło.","Luźne przedmioty mogą spaść i stanowić zagrożenie dla osób znajdujących się w pobliżu."],"l2-wind":["Przy silnym wietrze podwieszany jest duży ładunek. Co ma zastosowanie?","Komponent oferuje wiatrowi dużą powierzchnię do ataku.","Podnieś ładunek, nie biorąc pod uwagę ruchów kołysających.","Dodatkowe osoby powinny bezpośrednio trzymać ładunek.","Oceń warunki wietrzne i powstrzymaj się od podnoszenia, jeśli sytuacja jest niebezpieczna.","Siły wiatru mogą wpływać na prowadzenie ładunku i stabilność podczas transportu."],"l2-unterlage":["Dlaczego odpowiednie dokumenty są ważne podczas odsadzania?","Okrągły ładunek toczyłby się po ziemi.","Ładunek należy mocno osadzić i w razie potrzeby zabezpieczyć przed stoczeniem.","Pozostaw ładunek stojący bezpośrednio na zawiesiach.","Dokumenty należy wsunąć pod ładunek dopiero po ich odłożeniu.","Odpowiednie podpórki zapobiegają przewróceniu się i niepożądanym ruchom podczas siadania."],"l2-transportweg":["Co należy skoordynować przed transportem ładunku?","Ładunek jest przenoszony przez kilka obszarów roboczych.","Tylko oczekiwany czas trwania centrum.","Bezpieczna droga ładunku, komunikacja i niezbędne bariery.","Jedna osoba powinna wskazać drogę pod ładunkiem.","Transport ładunków wymaga bezpiecznych tras ruchu i jasnej koordynacji."],"l2-schutzschlauch":["Na co należy zwrócić uwagę stosując chusty z wężem ochronnym?","Zespół leży na ostrej krawędzi.","Dowolna cienka tkanina zastępuje odpowiednią ochronę krawędzi.","Wąż ochronny usuwa wszelkie dopuszczalne ograniczenia obciążenia.","Wybierz sprzęt ochronny zgodnie z przydatnością i wymaganiami zastosowania.","Sprzęt ochronny musi być dostosowany do materiału, krawędzi i zamierzonego obciążenia."],"l2-reinigung":["Pas do podnoszenia został zanieczyszczony nieznaną substancją chemiczną. Co jest słuszne?","Taśmy nie da się już jednoznacznie ocenić.","Przestań używać i profesjonalnie wyjaśnij zgodność lub stan.","Oczyścić dowolnym rozpuszczalnikiem i natychmiast kontynuować podnoszenie.","Zignoruj ​​środek chemiczny, dopóki taśma jest sucha.","Substancje chemiczne mogą wpływać na wytrzymałość zawiesi tekstylnych."],"l2-aufhaengung":["Co sprawdzasz pod kątem wielu pasm na łączniku zawieszenia?","Dwie nici są umieszczone razem w zawiesinie.","Pasmo może dowolnie przesuwać się na czubek haczyka.","Wszystkie elementy łączące muszą być odpowiednie i rozmieszczone zgodnie z przeznaczeniem.","Pierścień z pęknięciem można stosować przy małych obciążeniach.","Elementy zderzakowe i łączące muszą być nośne i prawidłowo rozmieszczone."],"l2-einweiserrolle":["Co ma zastosowanie, jeśli atakujący i operator dźwigu nie mają pola widzenia?","Przewoźnik zasłania widok na punkt zrzutu.","Koordynuj, dzwoniąc do kilku osób bez odpowiedzialności.","Przesuń ładunek w oparciu o hałas, bez instrukcji.","Zorganizuj jasną i bezpieczną komunikację i przerwij ją, jeśli jest niejasna.","Brak widoczności należy kompensować skuteczną koordynacją i bezpieczną komunikacją."],"l2-ausserbetrieb":["Uszkodzona chusta została naprawiona. Co jeszcze jest ważne?","Pozostaje swobodnie dostępny wraz z gotowymi do użycia zasobami.","Zabezpieczyć przed dalszym przypadkowym użyciem i poinformować osobę odpowiedzialną.","Zwróć produkt bez oznaczenia do magazynu.","Używaj go ponownie tylko w przypadku przenoszenia szczególnie lekkiego ładunku.","Wyrzucone zawiesia należy solidnie zabezpieczyć przed dalszym użyciem."],"b2-schwenkradius":["Dlaczego promień obrotu tylnego koparki ma kluczowe znaczenie?","Ogon porusza się po ograniczonym obszarze roboczym.","Osoby trzecie mogą zostać pochwycone przez kołyszącą się nadbudowę.","Promień obrotu nie ma wpływu na osoby znajdujące się w pobliżu maszyny.","Tył porusza się zawsze tylko w kierunku jazdy.","Podczas obrotu strefa niebezpieczna powstaje również za maszyną."],"b2-verkehrseinweiser":["W jaki sposób zabezpiecza się jazdę w przypadku ograniczonej widoczności?","Koparka musi manewrować za przeszkodą.","Jedź, nie widząc sygnałów sygnalizatora.","Jeśli to konieczne, zorganizuj odpowiednie instrukcje z jasną komunikacją.","Cofanie należy zabezpieczyć tylko jednokrotnym trąbieniem.","Mylące trasy wymagają skutecznych środków zapobiegających kolizjom i uwięzieniu."],"b2-standplatz":["Co dotyczy stojaka koparki na zboczu?","Podłoga jest nachylona i może być śliska.","Maszyna może rozciągać się tak daleko, jak chce, przy dowolnym nachyleniu.","Zawsze ustawiaj koparkę na luźnej warstwie ziemi.","Przed użyciem sprawdź stabilność i ograniczenia operacyjne maszyny.","Nachylenie zbocza i podłoże mają znaczący wpływ na stabilność."],"b2-oberleitung":["Dlaczego należy zaplanować odległość wysięgnika od linii energetycznych?","Podczas obracania wysięgnik może zbliżyć się do liny.","Przeskok elektryczny jest również możliwy bez bezpośredniego kontaktu.","Tylko łyżka może przewodzić prąd, a nie wysięgnik.","Przy suchej glebie każda odległość jest automatycznie bezpieczna.","Przed podejściem do instalacji elektrycznych należy ustalić granice użytkowania i odległości ochronne."],"b2-fremdperson":["Na plac budowy w strefie panoramowania wchodzi przechodzień. Co jest słuszne?","Osoba nagle staje w pobliżu łyżki koparki.","Podnieś łopatę i przesuń ją nad osobą.","Natychmiast zatrzymaj ruch i oczyść teren.","Po prostu kontynuuj obserwowanie osoby z bocznego okna.","Ruchy robocze nie mogą stwarzać zagrożenia dla osób znajdujących się w obszarze zagrożenia."],"b2-parkstellung":["Jak zabezpieczana jest maszyna do robót ziemnych po zakończeniu pracy?","Koparka pozostaje bez nadzoru na placu budowy.","Pozostaw łyżkę na wysokości głowy.","Pozwól silnikowi pracować bez nadzoru.","Odłóż sprzęt roboczy, zabezpiecz maszynę i zabezpiecz przed nieuprawnionym użyciem.","Właściwe parkowanie ogranicza ryzyko przypadkowego ruchu i nieuprawnionego dostępu."],"b2-eigenlast":["Dlaczego limity wyposażenia mają kluczowe znaczenie podczas podnoszenia za pomocą koparki?","Ciężki ładunek należy podnieść na wysięgniku.","W przeciwnym razie może zostać przekroczona stabilność i dopuszczalna nośność.","Każda maszyna może podnieść dowolny ładunek, o ile łyżka się zmieści.","Tylko długość liny zawiesia określa ryzyko.","Informacje o udźwigu i udźwigu zależą od sprzętu i sytuacji zastosowania."],"b2-untergrundhohlraum":["Podłoga nad starą piwnicą może być pusta. Co robisz?","Powinieneś wjechać koparką w ten teren.","Przejdź przez miejsce z maksymalnym pędem.","Przed dalszą jazdą należy sprawdzić nośność i ewentualne ubytki.","Po prostu umieść duży ładunek na powierzchni.","Wnęki mogą zapaść się pod ciężarem maszyny i spowodować awarię maszyny."],"b2-feuchtigkeit":["Po ulewnych deszczach nasyp staje się miękki. Co jest słuszne?","Koparka pracuje w pobliżu krawędzi nasypu.","Przesuń maszynę bliżej krawędzi, aby zwiększyć zasięg.","Ignoruj ​​zmiany do końca zmiany.","Ponownie oceń warunki gruntu i stabilność.","Wnikanie wilgoci może zmienić nośność i stabilność nasypów."],"b2-bodenprobe":["Dlaczego plany rurociągów należy sprawdzić przed rozpoczęciem wykopów?","Pod planowanym wykopem można było poprowadzić kable.","Umożliwia to identyfikację linii i zaplanowanie odpowiednich środków bezpieczeństwa.","Dzięki temu wykopy można przeprowadzić szybciej, niezależnie od systemów innych firm.","Ponieważ maszyn nie wolno nigdy używać w pobliżu kabli.","Podziemne linie zasilające wymagają dokładnego ustalenia lokalizacji przed rozpoczęciem prac wykopaliskowych."],"b2-maschinenzugang":["Co obowiązuje podczas wsiadania i wysiadania z maszyny do robót ziemnych?","Maszyna znajduje się na nierównym terenie.","Wysuń przewód hydrauliczny z kabiny.","Korzystaj z wyznaczonych schodów i upewnij się, że stoisz na bezpiecznym podłożu.","Wskocz na ramię obrotowe, gdy maszyna jest uruchomiona.","Bezpieczne podjazdy i odpowiednie punkty zatrzymania zmniejszają ryzyko upadku i zmiażdżenia."],"b2-kupplung":["Jak sprawdzić nową koparkę po montażu?","Łyżka podłączana jest za pomocą szybkozłącza.","Oceniaj łyżkę tylko wizualnie z większej odległości.","Wejdź bezpośrednio pod podniesioną łyżkę.","Zapewnij prawidłowe blokowanie i zalecane kroki kontrolne.","Osprzęt, który jest nieprawidłowo zablokowany, może się poluzować i stanowić zagrożenie dla ludzi."],"b2-hydraulikwartung":["Dlaczego przewody hydrauliczne nie mogą być otwierane pod ciśnieniem?","Należy wymienić wąż.","Wyciekający płyn może spowodować poważne obrażenia na skutek wysokiego ciśnienia.","Ciśnienie zawsze zapobiega wyciekowi oleju.","Otwartą linię można bezpiecznie sprawdzić rękami.","Płyn pod wysokim ciśnieniem może penetrować tkankę i wymaga bezpiecznego obniżenia ciśnienia."],"b2-fahrweg":["Musisz przejechać przez tymczasowy most budowlany. Co sprawdzasz?","Most jest przeznaczony tylko do określonych obciążeń.","Czy kolor mostu pasuje do maszyny.","Nośność i dopasowanie do masy i wymiarów maszyny.","Tylko czy po moście przejechał już lekki samochód.","Konstrukcje tymczasowe można stosować wyłącznie w zakresie ich udowodnionej nośności."],"b2-baggertransport":["Co jest ważne przy transporcie koparki na naczepie niskopodwoziowej?","Maszyna zostaje przewieziona na kolejny plac budowy.","Pozwól, aby sprzęt roboczy wystawał luźno ponad krawędź.","Podczas jazdy trzymaj otwarte drzwi kabiny.","Zabezpiecz maszynę zgodnie ze specyfikacjami transportowymi i sprawdź sprzęt załadunkowy.","Zabezpieczenia transportowe i odpowiednie urządzenia załadunkowe zapobiegają poślizgowi i upadkowi."],"b2-schaufelfuellung":["Dlaczego ładowarka kołowa nie może jechać szybko z wysoko podniesioną łyżką?","Ładunek jest duży, a podłoże nierówne.","Wysoko położony środek ciężkości może zwiększać ryzyko przewrócenia się i problemów z widocznością.","Łyżka stabilizuje się automatycznie przy dużych prędkościach.","Wysokość łopaty nie ma znaczenia dla stabilności.","Podniesiony środek ciężkości zazwyczaj pogarsza stabilność podczas jazdy i pokonywania zakrętów."],"b2-fussgaenger":["Jak się zachowujesz, manewrując obok pieszych?","Dojazd do placu budowy jest jednocześnie chodnikiem.","Użyj łopaty, aby skierować pieszych na bok.","Jazdę wykonuj tylko wtedy, gdy teren jest bezpiecznie czysty i możliwy do opanowania.","Wystarczy raz zatrąbić i jechać powoli, bez widoczności.","Ruch pojazdów i pasażerów musi być skutecznie oddzielony lub bezpiecznie koordynowany."],"b2-ueberlastwarnung":["Podczas podnoszenia maszyna zgłasza przeciążenie. Co robisz?","Podniesiony ładunek osiąga dopuszczalne wartości graniczne.","Wyłącz ostrzeżenie i kontynuuj podnoszenie go bez zmian.","Gwałtownie dokręć ładunek, gdy maszyna pracuje.","Zatrzymaj niebezpieczne ruchy i bezpiecznie popraw sytuację ładunku.","Ostrzeżenia o przeciążeniu wskazują możliwe przekroczenia limitów i zagrożenia stabilności."],"b2-wasserleitung":["Podczas kopania zostaje odkryta nieznana rura. Co ma zastosowanie?","Linia nie jest pokazana na planach budowy.","Przerwij pracę w dotkniętym obszarze i zleć profesjonalną identyfikację linii.","Spróbuj przesunąć linę za pomocą łyżki koparki.","Kontynuuj kopanie bezpośrednio pod linią, bez sprawdzania.","Nieznane linie mogą powodować zagrożenia elektryczne, gazowe lub wodne."],"b2-hangefahrt":["Jak prowadzić koparkę po stromym zboczu?","Planowana trasa prowadzi po zboczu.","Jedź po zboczu niezależnie od ograniczeń producenta.","Należy przestrzegać dopuszczalnego nachylenia i zalecanego stylu jazdy maszyny.","Odsuń wysięgnik daleko, aby zrównoważyć pojazd.","Dopuszczalne nachylenie zależy od maszyny, powierzchni i informacji producenta."],"b2-schlechtebeleuchtung":["Podczas pracy w ciemnym wykopie widoczność jest niewystarczająca. Co jest słuszne?","Prawie nie widać ludzi i przeszkód.","Zwiększ prędkość kopania, aby szybko zakończyć operację.","Nie używaj świateł, gdy silnik pracuje.","Przerwij pracę do czasu, aż obszary zagrożenia staną się wystarczająco widoczne.","Aby zapewnić kontrolowane ruchy maszyny, wymagana jest bezpieczna widoczność obszarów jazdy i pracy."],"b2-kettenverschleiss":["Podczas codziennej kontroli zauważono uszkodzoną gąsienicę. Co robisz?","Połączenie łańcucha wykazuje wyraźne uszkodzenia.","Nie używaj maszyny w sposób niekontrolowany i zgłoś wszelkie uszkodzenia.","Kontynuuj jazdę z dużą prędkością, aby łańcuch się wyprostował.","Kontynuuj pracę tylko na miękkim podłożu, bez sprawdzania.","Uszkodzenie napędu może pogorszyć sterowność i stabilność."],"b2-ladearbeiten":["Ładujesz ciężarówkę koparką. Co jest ważne?","Kierowca ciężarówki pozostaje blisko miejsca załadunku.","Przesuń łyżkę nad niezabezpieczoną kabiną kierowcy.","Zapobiegaj przebywaniu ludzi w strefie zagrożenia i koordynuj procesy.","Rozpocznij ładowanie bez komunikowania się ze sterownikiem.","Podczas załadunku istnieje ryzyko spadającego materiału i ruchów wahadłowych."],"b2-arbeitsunterbrechung":["Przerywasz prace wykopaliskowe ze względu na spotkanie. Co ma zastosowanie?","Maszyna powinna stać przez kilka minut bez obsługi.","Zostaw podniesioną łopatę jako znacznik.","Pozostaw maszynę bez nadzoru z włączonym napędem jezdnym.","Bezpiecznie odłóż narzędzie i zabezpiecz maszynę przed niezamierzonym użyciem.","Nawet krótkie przerwy wymagają bezpiecznego stanu maszyny."],"b2-rollmaterial":["Luźny materiał może spaść podczas transportu ładowarką kołową. Co jest słuszne?","Ładowarka podjeżdża blisko pracowników.","Podnieś ładunek bezpiecznie i wybierz bezpieczny styl jazdy z odpowiednią pozycją łyżki.","Podnieś łopatę tak wysoko, jak to możliwe, aby okolica była dobrze widoczna.","Podnieś ładunek bez ograniczania napełniania łyżki.","Luźne ładunki, wysokie położenie łyżek i słaba widoczność mogą stanowić zagrożenie dla ludzi i ruchu drogowego."]};
